-- Squashed schema (issue #505): folds the former 36 sequential migrations
-- into a single migration. Pre-release, no deployed data to preserve, and
-- four of those migrations rebuilt foreign-key-referenced tables via a
-- COMMIT; PRAGMA foreign_keys = OFF; ... BEGIN; dance -- SQLite refuses to
-- toggle PRAGMA foreign_keys inside any open transaction, at any nesting
-- depth, which made those migrations impossible to run under ADR 0068's
-- held write-lock transaction. Squashing removes every such rebuild step by
-- creating each table once, directly in its final shape.
--
-- Generated by diffing this file's applied result against the pre-squash
-- 36-migration chain (schema + seed data verified byte-identical). Seed
-- data (schema_meta.schema_init_at, the default video_profiles rows) is
-- carried forward unchanged in the "Seed data" section below.

CREATE TABLE schema_meta (
    key   TEXT PRIMARY KEY NOT NULL,
    value TEXT NOT NULL
) STRICT;
CREATE TABLE events (
    event_id     INTEGER PRIMARY KEY,
    occurred_at  TEXT NOT NULL,
    kind         TEXT NOT NULL,
    subject_type TEXT NOT NULL,
    subject_id   INTEGER,
    trace_id     TEXT,
    payload      TEXT NOT NULL,
    CHECK (json_valid(payload))
) STRICT;
CREATE INDEX events_by_subject ON events (subject_type, subject_id, occurred_at, event_id);
CREATE INDEX events_by_kind_time ON events (kind, occurred_at, event_id);
CREATE INDEX events_by_time ON events (occurred_at, event_id);
CREATE TRIGGER events_no_update
BEFORE UPDATE ON events
BEGIN SELECT RAISE(ABORT, 'events are append-only'); END;
CREATE TRIGGER events_no_delete
BEFORE DELETE ON events
BEGIN SELECT RAISE(ABORT, 'events are append-only'); END;
CREATE TABLE jobs (
    id          INTEGER PRIMARY KEY,
    kind        TEXT NOT NULL,
    state       TEXT NOT NULL CHECK (state IN ('open','succeeded','failed','cancelled')),
    priority    INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    epoch       INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX jobs_by_state_priority ON jobs (state, priority DESC, id);
CREATE TABLE tickets (
    id                INTEGER PRIMARY KEY,
    job_id            INTEGER REFERENCES jobs(id) ON DELETE RESTRICT,
    kind              TEXT NOT NULL,
    state             TEXT NOT NULL CHECK (state IN ('pending','ready','leased','succeeded','failed')),
    priority          INTEGER NOT NULL DEFAULT 0,
    payload           TEXT NOT NULL,
    result            TEXT,
    attempt           INTEGER NOT NULL DEFAULT 0,
    max_attempts      INTEGER NOT NULL DEFAULT 1 CHECK (max_attempts >= 1),
    next_eligible_at  TEXT NOT NULL,
    created_at        TEXT NOT NULL,
    state_changed_at  TEXT NOT NULL,
    epoch             INTEGER NOT NULL DEFAULT 0,
    CHECK (json_valid(payload)),
    CHECK (result IS NULL OR json_valid(result))
) STRICT;
CREATE INDEX tickets_by_state_priority
    ON tickets (state, priority DESC, next_eligible_at, id);
CREATE INDEX tickets_by_job ON tickets (job_id) WHERE job_id IS NOT NULL;
CREATE TABLE ticket_dependencies (
    id                     INTEGER PRIMARY KEY,
    ticket_id              INTEGER NOT NULL REFERENCES tickets(id) ON DELETE CASCADE,
    depends_on_ticket_id   INTEGER NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
    kind                   TEXT NOT NULL CHECK (kind IN ('phase')),
    UNIQUE (ticket_id, depends_on_ticket_id),
    CHECK (ticket_id != depends_on_ticket_id)
) STRICT;
CREATE INDEX ticket_dependencies_by_ticket ON ticket_dependencies (ticket_id);
CREATE INDEX ticket_dependencies_by_depends_on ON ticket_dependencies (depends_on_ticket_id);
CREATE TABLE workers (
    id             INTEGER PRIMARY KEY,
    name           TEXT NOT NULL UNIQUE,
    kind           TEXT NOT NULL CHECK (kind IN ('synthetic','local','remote')),
    status         TEXT NOT NULL CHECK (status IN ('registered','active','stale','retired')),
    registered_at  TEXT NOT NULL,
    last_seen_at   TEXT NOT NULL,
    retired_at     TEXT,
    epoch          INTEGER NOT NULL DEFAULT 0, node_id INTEGER REFERENCES nodes(id) ON DELETE RESTRICT, node_incarnation_id TEXT
    REFERENCES node_incarnations(incarnation_id) ON DELETE RESTRICT
    CHECK (node_incarnation_id IS NULL OR node_id IS NOT NULL),
    CHECK ((status = 'retired' AND retired_at IS NOT NULL)
        OR (status != 'retired' AND retired_at IS NULL))
) STRICT;
CREATE TABLE worker_capabilities (
    id                INTEGER PRIMARY KEY,
    worker_id         INTEGER NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    operation         TEXT NOT NULL,
    codecs            TEXT NOT NULL,
    hardware          TEXT NOT NULL,
    artifact_access   TEXT NOT NULL,
    extra             TEXT NOT NULL DEFAULT '{}',
    CHECK (json_valid(codecs)),
    CHECK (json_valid(hardware)),
    CHECK (json_valid(artifact_access)),
    CHECK (json_valid(extra))
) STRICT;
CREATE INDEX worker_capabilities_by_worker ON worker_capabilities (worker_id);
CREATE TABLE worker_grants (
    id                  INTEGER PRIMARY KEY,
    worker_id           INTEGER NOT NULL REFERENCES workers(id) ON DELETE CASCADE,
    can_execute         TEXT NOT NULL,
    can_access_read     TEXT NOT NULL,
    can_access_write    TEXT NOT NULL,
    denies              TEXT NOT NULL,
    max_parallel        TEXT NOT NULL,
    CHECK (json_valid(can_execute)),
    CHECK (json_valid(can_access_read)),
    CHECK (json_valid(can_access_write)),
    CHECK (json_valid(denies)),
    CHECK (json_valid(max_parallel))
) STRICT;
CREATE INDEX worker_grants_by_worker ON worker_grants (worker_id);
CREATE TABLE leases (
    id                  INTEGER PRIMARY KEY,
    ticket_id           INTEGER NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
    worker_id           INTEGER NOT NULL REFERENCES workers(id) ON DELETE RESTRICT,
    state               TEXT NOT NULL CHECK (state IN ('held','released','expired','force_released')),
    acquired_at         TEXT NOT NULL,
    expires_at          TEXT NOT NULL,
    last_heartbeat_at   TEXT NOT NULL,
    ttl_seconds         INTEGER NOT NULL CHECK (ttl_seconds > 0),
    release_reason      TEXT,
    released_at         TEXT,
    epoch               INTEGER NOT NULL DEFAULT 0,
    CHECK ((state = 'held'           AND release_reason IS NULL     AND released_at IS NULL)
        OR (state = 'released'       AND release_reason IS NOT NULL AND released_at IS NOT NULL)
        OR (state = 'expired'        AND release_reason IS NOT NULL AND released_at IS NOT NULL)
        OR (state = 'force_released' AND release_reason IS NOT NULL AND released_at IS NOT NULL))
) STRICT;
CREATE INDEX leases_held_by_expires_at
    ON leases (expires_at) WHERE state = 'held';
CREATE INDEX leases_by_ticket ON leases (ticket_id);
CREATE INDEX leases_by_worker ON leases (worker_id);
CREATE TABLE artifact_handles (
    id                    INTEGER PRIMARY KEY,
    size_bytes            INTEGER,
    checksum              TEXT,
    privacy_class         TEXT NOT NULL,
    durability_class      TEXT NOT NULL,
    allowed_access_modes  TEXT NOT NULL,
    mutability            TEXT NOT NULL,
    source_lineage        TEXT,
    created_at            TEXT NOT NULL, media_work_id    INTEGER REFERENCES media_works(id)    ON DELETE RESTRICT, media_variant_id INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT, asset_bundle_id  INTEGER REFERENCES asset_bundles(id)  ON DELETE RESTRICT, file_asset_id    INTEGER REFERENCES file_assets(id)    ON DELETE RESTRICT, file_version_id  INTEGER REFERENCES file_versions(id)  ON DELETE RESTRICT,
    CHECK (json_valid(allowed_access_modes)),
    CHECK (source_lineage IS NULL OR json_valid(source_lineage))
) STRICT;
CREATE TABLE artifact_locations (
    id                   INTEGER PRIMARY KEY,
    artifact_handle_id   INTEGER NOT NULL REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    kind                 TEXT NOT NULL CHECK (kind IN ('local_path','shared_mount','object_store','staging','backup')),
    value                TEXT NOT NULL,
    observed_at          TEXT NOT NULL,
    retired_at           TEXT
) STRICT;
CREATE INDEX artifact_locations_by_handle ON artifact_locations (artifact_handle_id);
CREATE INDEX artifact_locations_live
    ON artifact_locations (artifact_handle_id) WHERE retired_at IS NULL;
CREATE TABLE artifact_lineage (
    id                    INTEGER PRIMARY KEY,
    parent_artifact_id    INTEGER NOT NULL REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    child_artifact_id     INTEGER NOT NULL REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    operation             TEXT NOT NULL,
    recorded_at           TEXT NOT NULL,
    CHECK (parent_artifact_id != child_artifact_id)
) STRICT;
CREATE INDEX artifact_lineage_by_parent ON artifact_lineage (parent_artifact_id);
CREATE INDEX artifact_lineage_by_child ON artifact_lineage (child_artifact_id);
CREATE TABLE media_works (
    id             INTEGER PRIMARY KEY,
    kind           TEXT NOT NULL CHECK (kind IN ('movie','episode','personal','unknown')),
    display_title  TEXT NOT NULL,
    provisional    INTEGER NOT NULL DEFAULT 1 CHECK (provisional IN (0,1)),
    created_at     TEXT NOT NULL,
    epoch          INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE media_variants (
    id             INTEGER PRIMARY KEY,
    media_work_id  INTEGER NOT NULL REFERENCES media_works(id) ON DELETE RESTRICT,
    label          TEXT NOT NULL,
    provisional    INTEGER NOT NULL DEFAULT 1 CHECK (provisional IN (0,1)),
    created_at     TEXT NOT NULL,
    epoch          INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX media_variants_by_work ON media_variants (media_work_id);
CREATE TABLE file_assets (
    id          INTEGER PRIMARY KEY,
    created_at  TEXT NOT NULL,
    retired_at  TEXT,
    epoch       INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE TABLE asset_bundles (
    id                 INTEGER PRIMARY KEY,
    media_variant_id   INTEGER NOT NULL REFERENCES media_variants(id) ON DELETE RESTRICT,
    display_name       TEXT NOT NULL,
    created_at         TEXT NOT NULL,
    epoch              INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX asset_bundles_by_variant ON asset_bundles (media_variant_id);
CREATE TABLE identity_evidence (
    id                       INTEGER PRIMARY KEY,
    target_type              TEXT NOT NULL
        CHECK (target_type IN ('media_work','media_variant','asset_bundle',
                               'file_asset','file_version','file_location')),
    target_id                INTEGER NOT NULL,
    assertion_type           TEXT NOT NULL,
    candidate_id             INTEGER,
    candidate_value          TEXT,
    provider                 TEXT NOT NULL,
    provider_version         TEXT NOT NULL,
    confidence               REAL NOT NULL CHECK (confidence >= 0.0 AND confidence <= 1.0),
    provenance               TEXT NOT NULL,
    observed_at              TEXT NOT NULL,
    superseded_at            TEXT,
    superseded_by_id         INTEGER REFERENCES identity_evidence(id) ON DELETE RESTRICT,
    accepted_at              TEXT,
    accepted_user_id         TEXT,
    accepted_policy_id       INTEGER,
    pinned_file_version_ids  TEXT,
    pinned_hashes            TEXT,
    pinned_locations         TEXT,
    CHECK (json_valid(provenance)),
    CHECK (pinned_file_version_ids IS NULL OR json_valid(pinned_file_version_ids)),
    CHECK (pinned_hashes IS NULL OR json_valid(pinned_hashes)),
    CHECK (pinned_locations IS NULL OR json_valid(pinned_locations)),
    -- supersession pair stays consistent: either both set or both null.
    CHECK ((superseded_at IS NULL AND superseded_by_id IS NULL)
        OR (superseded_at IS NOT NULL AND superseded_by_id IS NOT NULL)),
    -- accepted_at gates the pinned columns: a row is either un-accepted
    -- (all pinned_* null, no accepted_at) or accepted (accepted_at set,
    -- pinned_* free to be NULL or JSON arrays; the repo populates them
    -- at accept-time).
    CHECK ((accepted_at IS NULL AND accepted_user_id IS NULL
            AND accepted_policy_id IS NULL
            AND pinned_file_version_ids IS NULL
            AND pinned_hashes IS NULL
            AND pinned_locations IS NULL)
        OR accepted_at IS NOT NULL)
) STRICT;
CREATE INDEX identity_evidence_by_target
    ON identity_evidence (target_type, target_id);
CREATE INDEX identity_evidence_live
    ON identity_evidence (target_type, target_id)
    WHERE superseded_at IS NULL;
CREATE TABLE media_snapshots (
    id                INTEGER PRIMARY KEY,
    file_version_id   INTEGER NOT NULL REFERENCES file_versions(id) ON DELETE RESTRICT,
    probed_by         INTEGER REFERENCES workers(id) ON DELETE RESTRICT,
    probed_at         TEXT NOT NULL,
    payload           TEXT NOT NULL,
    CHECK (json_valid(payload))
) STRICT;
CREATE INDEX media_snapshots_by_version ON media_snapshots (file_version_id);
CREATE INDEX artifact_handles_by_media_work    ON artifact_handles (media_work_id)    WHERE media_work_id    IS NOT NULL;
CREATE INDEX artifact_handles_by_media_variant ON artifact_handles (media_variant_id) WHERE media_variant_id IS NOT NULL;
CREATE INDEX artifact_handles_by_asset_bundle  ON artifact_handles (asset_bundle_id)  WHERE asset_bundle_id  IS NOT NULL;
CREATE INDEX artifact_handles_by_file_asset    ON artifact_handles (file_asset_id)    WHERE file_asset_id    IS NOT NULL;
CREATE INDEX artifact_handles_by_file_version  ON artifact_handles (file_version_id)  WHERE file_version_id  IS NOT NULL;
CREATE TABLE asset_use_leases (
    id                  INTEGER PRIMARY KEY,
    kind                TEXT NOT NULL
        CHECK (kind IN ('playback','scan','copy','manual_lock','external_lock','worker_operation')),
    scope_asset_id      INTEGER     REFERENCES file_assets(id)    ON DELETE RESTRICT,
    scope_bundle_id     INTEGER     REFERENCES asset_bundles(id)  ON DELETE RESTRICT,
    scope_version_id    INTEGER     REFERENCES file_versions(id)  ON DELETE RESTRICT,
    scope_location_id   INTEGER     REFERENCES file_locations(id) ON DELETE RESTRICT,
    issuer_kind         TEXT NOT NULL
        CHECK (issuer_kind IN ('user','control_plane','worker','external_system')),
    issuer_ref          TEXT NOT NULL,
    blocking_mode       TEXT NOT NULL
        CHECK (blocking_mode IN ('blocking','advisory')),
    ttl_bound           INTEGER NOT NULL CHECK (ttl_bound IN (0,1)),
    acquired_at         TEXT NOT NULL,
    expires_at          TEXT,
    last_heartbeat_at   TEXT,
    clock_source        TEXT NOT NULL CHECK (clock_source IN ('control_plane')),
    release_reason      TEXT
        CHECK (release_reason IS NULL OR release_reason IN
               ('released','expired','issuer_lost','superseded','force_released')),
    released_at         TEXT,
    epoch               INTEGER NOT NULL DEFAULT 0,
    -- TTL-bound leases carry an expires_at; manual locks do not.
    CHECK (
        (ttl_bound = 1 AND expires_at IS NOT NULL)
     OR (ttl_bound = 0 AND expires_at IS NULL)
    ),
    -- Terminal state requires both columns set; non-terminal requires both NULL.
    CHECK (
        (release_reason IS NULL AND released_at IS NULL)
     OR (release_reason IS NOT NULL AND released_at IS NOT NULL)
    ),
    -- Exactly one of the four scope_*_id columns is non-NULL.
    CHECK (
        (CASE WHEN scope_asset_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_bundle_id   IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_version_id  IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_location_id IS NULL THEN 0 ELSE 1 END)
      = 1
    )
) STRICT;
CREATE INDEX use_leases_by_asset
    ON asset_use_leases (scope_asset_id)
    WHERE scope_asset_id IS NOT NULL AND release_reason IS NULL;
CREATE INDEX use_leases_by_bundle
    ON asset_use_leases (scope_bundle_id)
    WHERE scope_bundle_id IS NOT NULL AND release_reason IS NULL;
CREATE INDEX use_leases_by_version
    ON asset_use_leases (scope_version_id)
    WHERE scope_version_id IS NOT NULL AND release_reason IS NULL;
CREATE INDEX use_leases_by_location
    ON asset_use_leases (scope_location_id)
    WHERE scope_location_id IS NOT NULL AND release_reason IS NULL;
CREATE INDEX use_leases_by_expiry
    ON asset_use_leases (expires_at)
    WHERE release_reason IS NULL AND ttl_bound = 1;
CREATE TABLE external_systems (
    id                  INTEGER PRIMARY KEY,
    kind                TEXT NOT NULL
        CHECK (kind IN ('plex','jellyfin','emby','radarr','sonarr','bazarr','s3','filesystem','custom')),
    display_name        TEXT NOT NULL,
    connection_profile  TEXT NOT NULL,
    auth_ref            TEXT NOT NULL,
    health_status       TEXT NOT NULL
        CHECK (health_status IN ('unknown','healthy','degraded','unreachable')),
    rate_limit_config   TEXT NOT NULL DEFAULT '{}',
    created_at          TEXT NOT NULL,
    retired_at          TEXT,
    epoch               INTEGER NOT NULL DEFAULT 0,
    CHECK (json_valid(connection_profile)),
    CHECK (json_valid(rate_limit_config))
) STRICT;
CREATE TABLE external_system_links (
    id                  INTEGER PRIMARY KEY,
    external_system_id  INTEGER NOT NULL REFERENCES external_systems(id) ON DELETE RESTRICT,
    target_type         TEXT NOT NULL
        CHECK (target_type IN ('media_work','media_variant','asset_bundle','file_asset')),
    target_id           INTEGER NOT NULL,
    external_ref        TEXT NOT NULL,
    created_at          TEXT NOT NULL,
    retired_at          TEXT
) STRICT;
CREATE INDEX external_system_links_by_system
    ON external_system_links (external_system_id)
    WHERE retired_at IS NULL;
CREATE INDEX external_system_links_by_target
    ON external_system_links (target_type, target_id)
    WHERE retired_at IS NULL;
CREATE TABLE external_path_mappings (
    id                  INTEGER PRIMARY KEY,
    external_system_id  INTEGER NOT NULL REFERENCES external_systems(id) ON DELETE RESTRICT,
    internal_prefix     TEXT NOT NULL,
    external_prefix     TEXT NOT NULL,
    visibility          TEXT NOT NULL
        CHECK (visibility IN ('read_only','read_write')),
    created_at          TEXT NOT NULL,
    retired_at          TEXT
) STRICT;
CREATE INDEX external_path_mappings_by_system
    ON external_path_mappings (external_system_id)
    WHERE retired_at IS NULL;
CREATE TABLE issues (
    id                INTEGER PRIMARY KEY,
    kind              TEXT NOT NULL
        CHECK (kind IN (
            'unknown_identity','missing_subtitle','duplicate_candidate',
            'policy_noncompliant','health_failed','external_sync_failed',
            'artifact_unavailable','variant_retention_conflict',
            'worker_untrusted','terminal_failure'
        )),
    severity          TEXT NOT NULL
        CHECK (severity IN ('critical','high','medium','low','info')),
    priority          TEXT NOT NULL
        CHECK (priority IN ('urgent','high','normal','low','someday')),
    priority_source   TEXT NOT NULL
        CHECK (priority_source IN ('system','user','policy','external')),
    priority_reason   TEXT,
    status            TEXT NOT NULL
        CHECK (status IN ('open','planned','resolved','suppressed','accepted')),
    suppressed_until  TEXT,
    title             TEXT NOT NULL,
    body              TEXT NOT NULL,
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL,
    resolved_at       TEXT,
    epoch             INTEGER NOT NULL DEFAULT 0, dedupe_key TEXT,
    -- Resolved status implies a resolved_at timestamp; non-resolved leaves it NULL.
    CHECK (
        (status = 'resolved' AND resolved_at IS NOT NULL)
     OR (status <> 'resolved' AND resolved_at IS NULL)
    ),
    -- Suppressed status implies a suppressed_until horizon; non-suppressed leaves it NULL.
    CHECK (
        (status = 'suppressed' AND suppressed_until IS NOT NULL)
     OR (status <> 'suppressed' AND suppressed_until IS NULL)
    )
) STRICT;
CREATE INDEX issues_by_status_priority
    ON issues (status, priority);
CREATE INDEX issues_by_kind
    ON issues (kind);
CREATE TABLE issue_links (
    id           INTEGER PRIMARY KEY,
    issue_id     INTEGER NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
    link_type    TEXT NOT NULL
        CHECK (link_type IN ('evidence','file_asset','bundle','worker',
                             'external_system','ticket','lease','use_lease')),
    target_type  TEXT NOT NULL,
    target_id    INTEGER NOT NULL,
    created_at   TEXT NOT NULL
) STRICT;
CREATE INDEX issue_links_by_issue
    ON issue_links (issue_id);
CREATE INDEX issue_links_by_target
    ON issue_links (target_type, target_id);
CREATE TABLE quality_scoring_profiles (
    id          INTEGER PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    version     INTEGER NOT NULL,
    definition  TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    retired_at  TEXT,
    CHECK (json_valid(definition))
) STRICT;
CREATE TABLE quality_scores (
    id                INTEGER PRIMARY KEY,
    profile_id        INTEGER NOT NULL REFERENCES quality_scoring_profiles(id) ON DELETE RESTRICT,
    profile_version   INTEGER NOT NULL,
    provider          TEXT NOT NULL,
    provider_version  TEXT NOT NULL,
    target_type       TEXT NOT NULL
        CHECK (target_type IN ('media_variant','asset_bundle','file_asset','file_version')),
    target_id         INTEGER NOT NULL,
    total_score       REAL NOT NULL,
    dimension_scores  TEXT NOT NULL,
    provenance        TEXT NOT NULL,
    observed_at       TEXT NOT NULL,
    superseded_at     TEXT,
    CHECK (json_valid(dimension_scores)),
    CHECK (json_valid(provenance))
) STRICT;
CREATE INDEX quality_scores_by_target
    ON quality_scores (target_type, target_id)
    WHERE superseded_at IS NULL;
CREATE INDEX quality_scores_by_profile
    ON quality_scores (profile_id)
    WHERE superseded_at IS NULL;
CREATE TABLE commit_intents (
    id                    INTEGER PRIMARY KEY,
    target                TEXT NOT NULL,    -- JSON-encoded CommitTarget
    closure_initial       TEXT NOT NULL,    -- JSON-encoded AffectedScopeClosure
    closure_authorized    TEXT,             -- JSON; set at Phase B success
    accepted_evidence_ids TEXT NOT NULL,    -- JSON array of EvidenceId values
    override_token        TEXT,             -- JSON-encoded ForcePathToken | NULL
    -- Per-member epoch snapshot taken inside the Phase B authorize tx.
    -- JSON array of [kind, row_id, epoch] triples. NOT NULL for any state
    -- the row has reached past 'pending' (authorize sets it; finalize
    -- and recovery-required preserve it; aborted-from-pending leaves it
    -- NULL since prepare never had a snapshot).
    target_row_epochs     TEXT,
    state                 TEXT NOT NULL
        CHECK (state IN ('pending','authorized','completed','aborted','recovery_required')),
    started_at            TEXT NOT NULL,
    authorized_at         TEXT,
    finalized_at          TEXT,
    aborted_at            TEXT,
    abort_reason          TEXT,
    -- Reason the row is in 'recovery_required'. Mutually exclusive with
    -- abort_reason: aborted rows have abort_reason; recovery_required rows
    -- have recovery_reason. The split keeps recovery-tooling queries
    -- single-column.
    recovery_reason       TEXT,
    epoch                 INTEGER NOT NULL DEFAULT 0,
    -- Exclusive-shape encoding: each state value owns the full column shape
    -- so contradictory rows are unrepresentable.
    CHECK (
           (state = 'pending'           AND authorized_at IS NULL     AND finalized_at IS NULL     AND aborted_at IS NULL     AND abort_reason IS NULL     AND recovery_reason IS NULL     AND target_row_epochs IS NULL)
        OR (state = 'authorized'        AND authorized_at IS NOT NULL AND finalized_at IS NULL     AND aborted_at IS NULL     AND abort_reason IS NULL     AND recovery_reason IS NULL     AND target_row_epochs IS NOT NULL AND closure_authorized IS NOT NULL)
        OR (state = 'completed'         AND authorized_at IS NOT NULL AND finalized_at IS NOT NULL AND aborted_at IS NULL     AND abort_reason IS NULL     AND recovery_reason IS NULL     AND target_row_epochs IS NOT NULL AND closure_authorized IS NOT NULL)
        OR (state = 'aborted'           AND finalized_at IS NULL      AND aborted_at IS NOT NULL   AND abort_reason IS NOT NULL AND recovery_reason IS NULL)
        OR (state = 'recovery_required' AND authorized_at IS NOT NULL AND finalized_at IS NULL     AND aborted_at IS NULL     AND abort_reason IS NULL     AND recovery_reason IS NOT NULL AND target_row_epochs IS NOT NULL AND closure_authorized IS NOT NULL)
    ),
    CHECK (override_token IS NULL OR json_valid(override_token)),
    CHECK (target_row_epochs IS NULL OR json_valid(target_row_epochs)),
    CHECK (json_valid(target)),
    CHECK (json_valid(closure_initial)),
    CHECK (closure_authorized IS NULL OR json_valid(closure_authorized)),
    CHECK (json_valid(accepted_evidence_ids))
) STRICT;
CREATE INDEX commit_intents_in_flight
    ON commit_intents (state, started_at)
    WHERE state IN ('pending','authorized');
CREATE TABLE commit_intent_scope_members (
    id                INTEGER PRIMARY KEY,
    commit_intent_id  INTEGER NOT NULL REFERENCES commit_intents(id) ON DELETE CASCADE,
    scope_asset_id    INTEGER REFERENCES file_assets(id)    ON DELETE RESTRICT,
    scope_bundle_id   INTEGER REFERENCES asset_bundles(id)  ON DELETE RESTRICT,
    scope_version_id  INTEGER REFERENCES file_versions(id)  ON DELETE RESTRICT,
    scope_location_id INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    -- Exactly one of the four scope_*_id columns is non-NULL.
    CHECK (
        (CASE WHEN scope_asset_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_bundle_id   IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_version_id  IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN scope_location_id IS NULL THEN 0 ELSE 1 END)
      = 1
    )
) STRICT;
CREATE INDEX commit_intent_scope_members_by_intent
    ON commit_intent_scope_members (commit_intent_id);
CREATE INDEX commit_intent_scope_members_by_asset
    ON commit_intent_scope_members (scope_asset_id)
    WHERE scope_asset_id IS NOT NULL;
CREATE INDEX commit_intent_scope_members_by_bundle
    ON commit_intent_scope_members (scope_bundle_id)
    WHERE scope_bundle_id IS NOT NULL;
CREATE INDEX commit_intent_scope_members_by_version
    ON commit_intent_scope_members (scope_version_id)
    WHERE scope_version_id IS NOT NULL;
CREATE INDEX commit_intent_scope_members_by_location
    ON commit_intent_scope_members (scope_location_id)
    WHERE scope_location_id IS NOT NULL;
CREATE TABLE policy_input_sets (
    id              INTEGER PRIMARY KEY,
    slug            TEXT NOT NULL UNIQUE,
    display_name    TEXT NOT NULL,
    schema_version  INTEGER NOT NULL CHECK (schema_version > 0),
    source_kind     TEXT NOT NULL CHECK (source_kind IN ('fixture','test','imported','manual')),
    created_at      TEXT NOT NULL,
    description     TEXT,
    epoch           INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX policy_input_sets_by_source_kind
    ON policy_input_sets (source_kind, created_at);
CREATE TABLE policy_input_set_fixture_labels (
    id                  INTEGER PRIMARY KEY,
    policy_input_set_id INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    label               TEXT NOT NULL,
    UNIQUE (label),
    UNIQUE (policy_input_set_id, label)
) STRICT;
CREATE INDEX policy_input_set_fixture_labels_by_set
    ON policy_input_set_fixture_labels (policy_input_set_id);
CREATE TABLE policy_input_synthetic_targets (
    id                  INTEGER PRIMARY KEY,
    policy_input_set_id INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    synthetic_key       TEXT NOT NULL,
    target_kind         TEXT NOT NULL CHECK (target_kind IN ('media_work','media_variant','asset_bundle','file_asset','file_version','file_location')),
    display_name        TEXT,
    UNIQUE (policy_input_set_id, synthetic_key),
    UNIQUE (policy_input_set_id, id)
) STRICT;
CREATE INDEX policy_input_synthetic_targets_by_set
    ON policy_input_synthetic_targets (policy_input_set_id);
CREATE TABLE policy_media_snapshot_inputs (
    id                         INTEGER PRIMARY KEY,
    policy_input_set_id        INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    ordinal                    INTEGER NOT NULL CHECK (ordinal >= 0),
    media_work_id              INTEGER REFERENCES media_works(id) ON DELETE RESTRICT,
    media_variant_id           INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT,
    asset_bundle_id            INTEGER REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    file_asset_id              INTEGER REFERENCES file_assets(id) ON DELETE RESTRICT,
    file_version_id            INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    file_location_id           INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    synthetic_target_id        INTEGER,
    container                  TEXT,
    stream_summary             TEXT NOT NULL,
    video_codec                TEXT,
    width                      INTEGER CHECK (width IS NULL OR width >= 0),
    height                     INTEGER CHECK (height IS NULL OR height >= 0),
    hdr                        TEXT,
    bitrate                    INTEGER CHECK (bitrate IS NULL OR bitrate >= 0),
    duration_millis            INTEGER CHECK (duration_millis IS NULL OR duration_millis >= 0),
    audio_languages            TEXT NOT NULL DEFAULT '[]',
    subtitle_languages         TEXT NOT NULL DEFAULT '[]',
    health_flags               TEXT NOT NULL DEFAULT '[]',
    existing_media_snapshot_id INTEGER REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    FOREIGN KEY (policy_input_set_id, synthetic_target_id)
        REFERENCES policy_input_synthetic_targets(policy_input_set_id, id),
    CHECK (json_valid(stream_summary)),
    CHECK (json_valid(audio_languages)),
    CHECK (json_valid(subtitle_languages)),
    CHECK (json_valid(health_flags)),
    CHECK (
        (CASE WHEN media_work_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN media_variant_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN asset_bundle_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_asset_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_version_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_location_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN synthetic_target_id IS NULL THEN 0 ELSE 1 END)
      = 1
    ),
    UNIQUE (policy_input_set_id, ordinal)
) STRICT;
CREATE INDEX policy_media_snapshot_inputs_by_set
    ON policy_media_snapshot_inputs (policy_input_set_id, ordinal);
CREATE TABLE policy_identity_evidence_inputs (
    id                   INTEGER PRIMARY KEY,
    policy_input_set_id  INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    ordinal              INTEGER NOT NULL CHECK (ordinal >= 0),
    media_work_id        INTEGER REFERENCES media_works(id) ON DELETE RESTRICT,
    media_variant_id     INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT,
    asset_bundle_id      INTEGER REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    file_asset_id        INTEGER REFERENCES file_assets(id) ON DELETE RESTRICT,
    file_version_id      INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    file_location_id     INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    synthetic_target_id  INTEGER,
    assertion_type       TEXT NOT NULL,
    provider             TEXT NOT NULL,
    provider_version     TEXT NOT NULL,
    confidence           REAL NOT NULL CHECK (confidence >= 0.0 AND confidence <= 1.0),
    provenance           TEXT NOT NULL,
    observed_at          TEXT NOT NULL,
    existing_evidence_id INTEGER REFERENCES identity_evidence(id) ON DELETE RESTRICT,
    FOREIGN KEY (policy_input_set_id, synthetic_target_id)
        REFERENCES policy_input_synthetic_targets(policy_input_set_id, id),
    CHECK (json_valid(provenance)),
    CHECK (
        (CASE WHEN media_work_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN media_variant_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN asset_bundle_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_asset_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_version_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_location_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN synthetic_target_id IS NULL THEN 0 ELSE 1 END)
      = 1
    ),
    UNIQUE (policy_input_set_id, ordinal)
) STRICT;
CREATE INDEX policy_identity_evidence_inputs_by_set
    ON policy_identity_evidence_inputs (policy_input_set_id, ordinal);
CREATE TABLE policy_bundle_target_inputs (
    id                       INTEGER PRIMARY KEY,
    policy_input_set_id      INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    ordinal                  INTEGER NOT NULL CHECK (ordinal >= 0),
    media_work_id            INTEGER REFERENCES media_works(id) ON DELETE RESTRICT,
    media_variant_id         INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT,
    asset_bundle_id          INTEGER REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    file_asset_id            INTEGER REFERENCES file_assets(id) ON DELETE RESTRICT,
    file_version_id          INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    file_location_id         INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    synthetic_target_id      INTEGER,
    role                     TEXT NOT NULL,
    desired_state            TEXT NOT NULL CHECK (desired_state IN ('required','allowed','forbidden','preferred')),
    language                 TEXT,
    label                    TEXT,
    disposition              TEXT,
    artifact_expectation     TEXT NOT NULL,
    FOREIGN KEY (policy_input_set_id, synthetic_target_id)
        REFERENCES policy_input_synthetic_targets(policy_input_set_id, id),
    CHECK (json_valid(artifact_expectation)),
