        (CASE WHEN media_work_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN media_variant_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN asset_bundle_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_asset_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_version_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_location_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN synthetic_target_id IS NULL THEN 0 ELSE 1 END)
      = 1
    ),
    UNIQUE (policy_input_set_id, ordinal)
) STRICT;
CREATE INDEX policy_bundle_target_inputs_by_set
    ON policy_bundle_target_inputs (policy_input_set_id, ordinal);
CREATE TABLE policy_quality_profile_selections (
    id                  INTEGER PRIMARY KEY,
    policy_input_set_id INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    ordinal             INTEGER NOT NULL CHECK (ordinal >= 0),
    media_work_id       INTEGER REFERENCES media_works(id) ON DELETE RESTRICT,
    media_variant_id    INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT,
    asset_bundle_id     INTEGER REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    file_asset_id       INTEGER REFERENCES file_assets(id) ON DELETE RESTRICT,
    file_version_id     INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    file_location_id    INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    synthetic_target_id INTEGER,
    profile_name        TEXT NOT NULL,
    profile_version     TEXT NOT NULL,
    dimension_weights   TEXT NOT NULL,
    FOREIGN KEY (policy_input_set_id, synthetic_target_id)
        REFERENCES policy_input_synthetic_targets(policy_input_set_id, id),
    CHECK (json_valid(dimension_weights)),
    CHECK (
        (CASE WHEN media_work_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN media_variant_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN asset_bundle_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_asset_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_version_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_location_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN synthetic_target_id IS NULL THEN 0 ELSE 1 END)
      = 1
    ),
    UNIQUE (policy_input_set_id, ordinal)
) STRICT;
CREATE INDEX policy_quality_profile_selections_by_set
    ON policy_quality_profile_selections (policy_input_set_id, ordinal);
CREATE TABLE policy_issue_inputs (
    id                  INTEGER PRIMARY KEY,
    policy_input_set_id INTEGER NOT NULL REFERENCES policy_input_sets(id) ON DELETE CASCADE,
    ordinal             INTEGER NOT NULL CHECK (ordinal >= 0),
    media_work_id       INTEGER REFERENCES media_works(id) ON DELETE RESTRICT,
    media_variant_id    INTEGER REFERENCES media_variants(id) ON DELETE RESTRICT,
    asset_bundle_id     INTEGER REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    file_asset_id       INTEGER REFERENCES file_assets(id) ON DELETE RESTRICT,
    file_version_id     INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    file_location_id    INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    synthetic_target_id INTEGER,
    kind                TEXT NOT NULL,
    severity            TEXT NOT NULL CHECK (severity IN ('critical','high','medium','low','info')),
    priority            TEXT NOT NULL CHECK (priority IN ('urgent','high','normal','low','someday')),
    state               TEXT NOT NULL CHECK (state IN ('open','accepted','suppressed','planned')),
    reason              TEXT NOT NULL,
    provenance          TEXT NOT NULL,
    existing_issue_id   INTEGER REFERENCES issues(id) ON DELETE RESTRICT,
    FOREIGN KEY (policy_input_set_id, synthetic_target_id)
        REFERENCES policy_input_synthetic_targets(policy_input_set_id, id),
    CHECK (json_valid(provenance)),
    CHECK (
        (CASE WHEN media_work_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN media_variant_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN asset_bundle_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_asset_id       IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_version_id     IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN file_location_id    IS NULL THEN 0 ELSE 1 END)
      + (CASE WHEN synthetic_target_id IS NULL THEN 0 ELSE 1 END)
      = 1
    ),
    UNIQUE (policy_input_set_id, ordinal)
) STRICT;
CREATE INDEX policy_issue_inputs_by_set
    ON policy_issue_inputs (policy_input_set_id, ordinal);
CREATE TABLE policy_documents (
    id                          INTEGER PRIMARY KEY,
    slug                        TEXT NOT NULL UNIQUE,
    display_name                TEXT NOT NULL,
    created_at                  TEXT NOT NULL,
    current_accepted_version_id INTEGER,
    epoch                       INTEGER NOT NULL DEFAULT 0,
    CHECK (length(trim(slug)) > 0),
    CHECK (slug NOT GLOB '*[^a-z0-9_-]*'),
    CHECK (length(trim(display_name)) > 0),
    CHECK (epoch >= 0)
) STRICT;
CREATE TABLE policy_versions (
    id                 INTEGER PRIMARY KEY,
    policy_document_id INTEGER NOT NULL REFERENCES policy_documents(id) ON DELETE RESTRICT,
    version_number     INTEGER NOT NULL,
    source_text        TEXT NOT NULL,
    source_hash        TEXT NOT NULL,
    schema_version     INTEGER NOT NULL,
    compiled_json      TEXT NOT NULL CHECK (json_valid(compiled_json)),
    created_at         TEXT NOT NULL,
    CHECK (version_number > 0),
    CHECK (length(source_hash) = 64),
    CHECK (source_hash NOT GLOB '*[^0-9a-f]*'),
    CHECK (schema_version > 0),
    UNIQUE (policy_document_id, version_number),
    UNIQUE (policy_document_id, source_hash),
    UNIQUE (policy_document_id, id)
) STRICT;
CREATE INDEX policy_documents_by_slug
    ON policy_documents (slug);
CREATE INDEX policy_versions_by_document
    ON policy_versions (policy_document_id, version_number);
CREATE TRIGGER policy_documents_current_version_same_document_insert
BEFORE INSERT ON policy_documents
WHEN NEW.current_accepted_version_id IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'policy current version must belong to document')
    WHERE NOT EXISTS (
        SELECT 1 FROM policy_versions
        WHERE id = NEW.current_accepted_version_id
          AND policy_document_id = NEW.id
    );
END;
CREATE TRIGGER policy_documents_current_version_same_document_update
BEFORE UPDATE OF current_accepted_version_id ON policy_documents
WHEN NEW.current_accepted_version_id IS NOT NULL
BEGIN
    SELECT RAISE(ABORT, 'policy current version must belong to document')
    WHERE NOT EXISTS (
        SELECT 1 FROM policy_versions
        WHERE id = NEW.current_accepted_version_id
          AND policy_document_id = NEW.id
    );
END;
CREATE TRIGGER policy_versions_are_immutable
BEFORE UPDATE ON policy_versions
BEGIN
    SELECT RAISE(ABORT, 'policy versions are immutable');
END;
CREATE TRIGGER policy_versions_are_not_deleted
BEFORE DELETE ON policy_versions
BEGIN
    SELECT RAISE(ABORT, 'policy versions are immutable');
END;
CREATE UNIQUE INDEX issues_dedupe_key_unique
    ON issues (dedupe_key)
    WHERE dedupe_key IS NOT NULL;
CREATE TABLE nodes (
    id                      INTEGER PRIMARY KEY,
    name                    TEXT NOT NULL UNIQUE,
    kind                    TEXT NOT NULL CHECK (kind IN ('local','remote','synthetic')),
    status                  TEXT NOT NULL CHECK (status IN ('registered','active','stale','retired')),
    registered_at           TEXT NOT NULL,
    last_seen_at            TEXT NOT NULL,
    retired_at              TEXT,
    heartbeat_ttl_seconds   INTEGER NOT NULL CHECK (heartbeat_ttl_seconds > 0),
    auth_token_hash         TEXT NOT NULL,
    auth_token_hint         TEXT NOT NULL,
    metadata                TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata)),
    epoch                   INTEGER NOT NULL DEFAULT 0, active_incarnation_id TEXT
    REFERENCES node_incarnations(incarnation_id) ON DELETE RESTRICT,
    CHECK ((status = 'retired' AND retired_at IS NOT NULL)
        OR (status != 'retired' AND retired_at IS NULL))
) STRICT;
CREATE INDEX nodes_by_status_seen ON nodes (status, last_seen_at, id);
CREATE INDEX workers_by_node ON workers (node_id) WHERE node_id IS NOT NULL;
CREATE TABLE remote_idempotency_keys (
    id                  INTEGER PRIMARY KEY,
    node_id             INTEGER NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT,
    route_key           TEXT NOT NULL,
    worker_scope_id     INTEGER NOT NULL,
    worker_id           INTEGER REFERENCES workers(id) ON DELETE RESTRICT,
    idempotency_key     TEXT NOT NULL,
    request_hash        TEXT NOT NULL,
    response_json       TEXT CHECK (response_json IS NULL OR json_valid(response_json)),
    status              TEXT NOT NULL CHECK (status IN ('in_progress','completed')),
    created_at          TEXT NOT NULL,
    UNIQUE (node_id, route_key, worker_scope_id, idempotency_key),
    CHECK ((worker_scope_id = 0 AND worker_id IS NULL)
        OR (worker_scope_id > 0 AND worker_id IS NOT NULL AND worker_scope_id = worker_id)),
    CHECK ((status = 'in_progress' AND response_json IS NULL)
        OR (status = 'completed' AND response_json IS NOT NULL))
) STRICT;
CREATE INDEX remote_idempotency_by_node_created
    ON remote_idempotency_keys (node_id, created_at, id);
CREATE TABLE artifact_access_plans (
    id                      INTEGER PRIMARY KEY,
    lease_id                INTEGER NOT NULL REFERENCES leases(id) ON DELETE RESTRICT,
    ticket_id               INTEGER NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
    worker_id               INTEGER NOT NULL REFERENCES workers(id) ON DELETE RESTRICT,
    node_id                 INTEGER NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT,
    input_handles           TEXT NOT NULL CHECK (json_valid(input_handles)),
    output_handles          TEXT NOT NULL CHECK (json_valid(output_handles)),
    selected_access_mode    TEXT NOT NULL CHECK (selected_access_mode IN (
                                'shared_mount',
                                'control_plane_placeholder',
                                'staged_output_placeholder'
                            )),
    status                  TEXT NOT NULL CHECK (status IN ('selected','consumed','rejected','failed')),
    reason                  TEXT,
    evidence                TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(evidence)),
    created_at              TEXT NOT NULL,
    updated_at              TEXT NOT NULL,
    UNIQUE (lease_id)
) STRICT;
CREATE INDEX artifact_access_plans_by_ticket
    ON artifact_access_plans (ticket_id, id);
CREATE INDEX artifact_access_plans_by_worker
    ON artifact_access_plans (worker_id, id);
CREATE INDEX artifact_access_plans_by_node
    ON artifact_access_plans (node_id, id);
CREATE INDEX artifact_access_plans_by_mode_status
    ON artifact_access_plans (selected_access_mode, status, id);
CREATE TABLE scheduler_node_limits (
    node_id                 INTEGER PRIMARY KEY REFERENCES nodes(id) ON DELETE CASCADE,
    max_parallel_leases     INTEGER NOT NULL CHECK (max_parallel_leases > 0),
    created_at              TEXT NOT NULL,
    updated_at              TEXT NOT NULL
) STRICT;
CREATE TABLE scheduler_decisions (
    id                      INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at              TEXT NOT NULL,
    updated_at              TEXT NOT NULL,
    first_seen_at           TEXT NOT NULL,
    last_seen_at            TEXT NOT NULL,
    decision_kind           TEXT NOT NULL CHECK (decision_kind IN (
                                'lease_acquire',
                                'idle',
                                'no_candidate'
                            )),
    request_source          TEXT NOT NULL CHECK (request_source IN ('remote_acquire')),
    idempotency_key         TEXT,
    request_node_id         INTEGER REFERENCES nodes(id) ON DELETE SET NULL,
    request_worker_id       INTEGER REFERENCES workers(id) ON DELETE SET NULL,
    ticket_id               INTEGER REFERENCES tickets(id) ON DELETE SET NULL,
    selected_worker_id      INTEGER REFERENCES workers(id) ON DELETE SET NULL,
    selected_node_id        INTEGER REFERENCES nodes(id) ON DELETE SET NULL,
    selected_lease_id       INTEGER REFERENCES leases(id) ON DELETE SET NULL,
    outcome                 TEXT NOT NULL CHECK (outcome IN (
                                'selected',
                                'idle',
                                'no_eligible_candidate',
                                'rejected'
                            )),
    reason_code             TEXT NOT NULL CHECK (reason_code IN (
                                'selected',
                                'no_ready_ticket',
                                'missing_capability',
                                'missing_grant',
                                'operation_denied',
                                'worker_not_executable',
                                'node_not_executable',
                                'heartbeat_expired',
                                'unsupported_artifact_access',
                                'worker_capacity_full',
                                'node_capacity_full',
                                'no_eligible_candidate'
                            )),
    summary                 TEXT NOT NULL,
    candidate_count         INTEGER NOT NULL CHECK (candidate_count >= 0),
    selected_score          INTEGER,
    suppressed_count        INTEGER NOT NULL DEFAULT 0 CHECK (suppressed_count >= 0),
    suppression_key         TEXT CHECK (
                                suppression_key IS NULL
                                OR (
                                    decision_kind = 'idle'
                                    AND outcome = 'idle'
                                )
                                OR (
                                    decision_kind = 'no_candidate'
                                    AND outcome = 'no_eligible_candidate'
                                )
                            ),
    explanation_json        TEXT NOT NULL CHECK (json_valid(explanation_json)),
    CHECK (
        (
            decision_kind = 'lease_acquire'
            AND outcome = 'selected'
            AND reason_code = 'selected'
            AND candidate_count > 0
        )
        OR (
            decision_kind = 'idle'
            AND outcome = 'idle'
            AND reason_code = 'no_ready_ticket'
            AND candidate_count = 0
            AND ticket_id IS NULL
            AND selected_worker_id IS NULL
            AND selected_node_id IS NULL
            AND selected_lease_id IS NULL
            AND selected_score IS NULL
        )
        OR (
            decision_kind = 'no_candidate'
            AND outcome = 'no_eligible_candidate'
            AND reason_code != 'selected'
            AND candidate_count > 0
            AND selected_worker_id IS NULL
            AND selected_node_id IS NULL
            AND selected_lease_id IS NULL
            AND selected_score IS NULL
        )
        OR (
            decision_kind = 'lease_acquire'
            AND outcome = 'rejected'
            AND reason_code != 'selected'
            AND selected_worker_id IS NULL
            AND selected_node_id IS NULL
            AND selected_lease_id IS NULL
            AND selected_score IS NULL
        )
    )
) STRICT;
CREATE INDEX scheduler_decisions_by_created_at
    ON scheduler_decisions (created_at DESC, id DESC);
CREATE INDEX scheduler_decisions_by_ticket
    ON scheduler_decisions (ticket_id, id);
CREATE INDEX scheduler_decisions_by_request_worker
    ON scheduler_decisions (request_worker_id, id);
CREATE INDEX scheduler_decisions_by_request_node
    ON scheduler_decisions (request_node_id, id);
CREATE INDEX scheduler_decisions_by_selected_worker
    ON scheduler_decisions (selected_worker_id, id);
CREATE INDEX scheduler_decisions_by_selected_node
    ON scheduler_decisions (selected_node_id, id);
CREATE INDEX scheduler_decisions_by_outcome
    ON scheduler_decisions (outcome, id);
CREATE INDEX scheduler_decisions_by_reason_code
    ON scheduler_decisions (reason_code, id);
CREATE UNIQUE INDEX scheduler_decisions_by_suppression_key
    ON scheduler_decisions (suppression_key)
    WHERE suppression_key IS NOT NULL;
CREATE TABLE artifact_verifications (
    id                    INTEGER PRIMARY KEY,
    artifact_handle_id    INTEGER NOT NULL REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    artifact_location_id  INTEGER NOT NULL REFERENCES artifact_locations(id) ON DELETE RESTRICT,
    path                  TEXT NOT NULL,
    worker_id             INTEGER NOT NULL REFERENCES workers(id) ON DELETE RESTRICT,
    status                TEXT NOT NULL CHECK (status IN ('succeeded','failed')),
    expected_size_bytes   INTEGER NOT NULL CHECK (expected_size_bytes >= 0),
    expected_checksum     TEXT NOT NULL,
    observed_size_bytes   INTEGER CHECK (observed_size_bytes IS NULL OR observed_size_bytes >= 0),
    observed_checksum     TEXT,
    failure_class         TEXT,
    error_code            TEXT,
    message               TEXT,
    report                TEXT NOT NULL CHECK (json_valid(report)),
    started_at            TEXT NOT NULL,
    finished_at           TEXT NOT NULL, workflow_lease_id INTEGER REFERENCES leases(id) ON DELETE RESTRICT, workflow_ticket_id INTEGER REFERENCES tickets(id) ON DELETE RESTRICT
        CHECK ((workflow_ticket_id IS NULL) = (workflow_lease_id IS NULL)),
    CHECK (
           (status = 'succeeded' AND observed_size_bytes IS NOT NULL AND observed_checksum IS NOT NULL
            AND failure_class IS NULL AND error_code IS NULL AND message IS NULL)
        OR (status = 'failed' AND failure_class IS NOT NULL AND error_code IS NOT NULL AND message IS NOT NULL)
    )
) STRICT;
CREATE INDEX artifact_verifications_by_artifact
    ON artifact_verifications (artifact_handle_id, id DESC);
CREATE INDEX artifact_verifications_success_by_location
    ON artifact_verifications (artifact_handle_id, artifact_location_id, id DESC)
    WHERE status = 'succeeded';
CREATE TABLE artifact_commit_records (
    id                       INTEGER PRIMARY KEY,
    artifact_handle_id       INTEGER NOT NULL REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    source_file_version_id   INTEGER NOT NULL REFERENCES file_versions(id) ON DELETE RESTRICT,
    verification_id          INTEGER NOT NULL REFERENCES artifact_verifications(id) ON DELETE RESTRICT,
    target_path              TEXT NOT NULL,
    result_file_version_id   INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    result_file_location_id  INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    state                    TEXT NOT NULL CHECK (state IN ('pending','committed','failed','recovery_required')),
    failure_class            TEXT,
    error_code               TEXT,
    message                  TEXT,
    recovery_reason          TEXT,
    temp_path                TEXT,
    report                   TEXT NOT NULL CHECK (json_valid(report)),
    started_at               TEXT NOT NULL,
    promotion_started_at     TEXT,
    finished_at              TEXT,
    CHECK (
           (state = 'pending' AND result_file_version_id IS NULL AND result_file_location_id IS NULL
            AND failure_class IS NULL AND error_code IS NULL AND message IS NULL AND recovery_reason IS NULL
            AND finished_at IS NULL)
        OR (state = 'committed' AND result_file_version_id IS NOT NULL AND result_file_location_id IS NOT NULL
            AND failure_class IS NULL AND error_code IS NULL AND message IS NULL AND recovery_reason IS NULL
            AND finished_at IS NOT NULL)
        OR (state = 'failed' AND failure_class IS NOT NULL AND error_code IS NOT NULL AND message IS NOT NULL
            AND recovery_reason IS NULL AND finished_at IS NOT NULL)
        OR (state = 'recovery_required' AND failure_class IS NOT NULL AND error_code IS NOT NULL
            AND message IS NOT NULL AND recovery_reason IS NOT NULL AND finished_at IS NOT NULL)
    )
) STRICT;
CREATE UNIQUE INDEX artifact_commit_records_one_owner_per_artifact
    ON artifact_commit_records (artifact_handle_id)
    WHERE state IN ('pending','committed','recovery_required');
CREATE UNIQUE INDEX artifact_commit_records_one_owner_per_target
    ON artifact_commit_records (target_path)
    WHERE state IN ('pending','committed','recovery_required');
CREATE INDEX artifact_commit_records_by_state
    ON artifact_commit_records (state, started_at DESC);
CREATE TABLE asset_bundle_members (
    id              INTEGER PRIMARY KEY,
    bundle_id       INTEGER NOT NULL REFERENCES asset_bundles(id) ON DELETE CASCADE,
    file_asset_id   INTEGER NOT NULL REFERENCES file_assets(id) ON DELETE RESTRICT,
    role            TEXT NOT NULL
        CHECK (role IN ('primary_video','commentary_audio','external_audio',
                        'external_subtitle','poster','nfo','trailer','transcript',
                        'thumbnail','report')),
    UNIQUE (file_asset_id)
) STRICT;
CREATE INDEX asset_bundle_members_by_bundle ON asset_bundle_members (bundle_id);
CREATE TABLE file_versions (
    id                          INTEGER PRIMARY KEY,
    file_asset_id               INTEGER NOT NULL REFERENCES file_assets(id) ON DELETE RESTRICT,
    content_hash                TEXT NOT NULL,
    size_bytes                  INTEGER NOT NULL CHECK (size_bytes >= 0),
    produced_by                 TEXT NOT NULL
        CHECK (produced_by IN ('ingest','transcode','remux','restore','external_observed','staged_commit')),
    produced_from_version_id    INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    created_at                  TEXT NOT NULL,
    retired_at                  TEXT,
    epoch                       INTEGER NOT NULL DEFAULT 0,
    CHECK (
           (produced_by IN ('ingest','external_observed'))
        OR produced_from_version_id IS NOT NULL
    )
) STRICT;
CREATE INDEX file_versions_by_asset ON file_versions (file_asset_id);
CREATE INDEX file_versions_by_hash  ON file_versions (content_hash);
CREATE TABLE workflow_summaries (
    job_id                       INTEGER PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,
    branch_count                 INTEGER NOT NULL CHECK (branch_count >= 0),
    ticket_count                 INTEGER NOT NULL CHECK (ticket_count >= 0),
    dispatch_count               INTEGER NOT NULL CHECK (dispatch_count >= 0),
    retry_count                  INTEGER NOT NULL CHECK (retry_count >= 0),
    failure_count                INTEGER NOT NULL CHECK (failure_count >= 0),
    peak_active_workflow_leases  INTEGER NOT NULL CHECK (peak_active_workflow_leases >= 0),
    elapsed_ns                   INTEGER NOT NULL CHECK (elapsed_ns >= 0),
    per_operation                TEXT NOT NULL CHECK (json_valid(per_operation)),
    created_at                   TEXT NOT NULL
) STRICT;
CREATE TABLE workflow_phase_summaries (
    id            INTEGER PRIMARY KEY,
    job_id        INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    phase_ordinal INTEGER NOT NULL CHECK (phase_ordinal >= 0),
    phase_name    TEXT NOT NULL,
    report_id     TEXT,
    report        TEXT CHECK (report IS NULL OR json_valid(report)),
    outcome       TEXT NOT NULL
        CHECK (outcome IN ('completed', 'partially-committed', 'skipped', 'blocked')),
    created_at    TEXT NOT NULL,
    -- report_id and report live or die together (skipped/blocked phases have neither).
    CHECK ((report_id IS NULL AND report IS NULL)
        OR (report_id IS NOT NULL AND report IS NOT NULL))
) STRICT;
CREATE UNIQUE INDEX workflow_phase_summaries_key
    ON workflow_phase_summaries (job_id, phase_ordinal);
CREATE TABLE scan_file_facts (
    file_location_id INTEGER PRIMARY KEY
        REFERENCES file_locations (id) ON DELETE CASCADE,
    dev              INTEGER NOT NULL,
    ino              INTEGER NOT NULL,
    nlink            INTEGER NOT NULL,
    observed_at      TEXT NOT NULL
) STRICT;
CREATE INDEX idx_scan_file_facts_dev_ino ON scan_file_facts (dev, ino);
CREATE TABLE backups (
    id                     INTEGER PRIMARY KEY,
    source_file_version_id INTEGER NOT NULL REFERENCES file_versions(id) ON DELETE RESTRICT,
    job_id                 INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    ticket_id              INTEGER NOT NULL REFERENCES tickets(id) ON DELETE RESTRICT,
    provider               TEXT NOT NULL,
    destination_path       TEXT NOT NULL,
    size_bytes             INTEGER CHECK (size_bytes IS NULL OR size_bytes >= 0),
    checksum               TEXT,
    status                 TEXT NOT NULL CHECK (status IN ('pending', 'verified', 'failed')),
    failure_class          TEXT,
    error_code             TEXT,
    message                TEXT,
    started_at             TEXT NOT NULL,
    finished_at            TEXT,
    created_at             TEXT NOT NULL,
    CHECK (
           (status = 'pending'  AND size_bytes IS NULL AND checksum IS NULL
                AND failure_class IS NULL AND error_code IS NULL AND message IS NULL
                AND finished_at IS NULL)
        OR (status = 'verified' AND size_bytes IS NOT NULL AND checksum IS NOT NULL
                AND failure_class IS NULL AND error_code IS NULL AND message IS NULL
                AND finished_at IS NOT NULL)
        OR (status = 'failed'   AND failure_class IS NOT NULL AND error_code IS NOT NULL
                AND message IS NOT NULL AND finished_at IS NOT NULL)
    )
) STRICT;
CREATE INDEX backups_by_file_version ON backups (source_file_version_id, id DESC);
CREATE INDEX backups_by_job ON backups (job_id, id DESC);
CREATE UNIQUE INDEX backups_verified_key
    ON backups (ticket_id, source_file_version_id) WHERE status = 'verified';
CREATE TABLE libraries (
    id           INTEGER PRIMARY KEY,
    slug         TEXT NOT NULL,
    display_name TEXT NOT NULL,
    media_kind   TEXT NOT NULL
        CHECK (media_kind IN ('movie', 'episode', 'personal', 'unknown')),
    description  TEXT,
    enabled      INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
, default_scoring_profile_name TEXT) STRICT;
CREATE UNIQUE INDEX libraries_slug ON libraries (slug);
CREATE TABLE scheduling_policies (
    id                     INTEGER PRIMARY KEY,
    slug                   TEXT NOT NULL UNIQUE,
    display_name           TEXT NOT NULL,
    schema_version         INTEGER NOT NULL CHECK (schema_version >= 1),
    priority               TEXT NOT NULL CHECK (priority IN (
                               'newest_first', 'oldest_first',
                               'smallest_first', 'largest_first')),
    copy_window            TEXT,
    large_jobs_night_only  INTEGER NOT NULL CHECK (large_jobs_night_only IN (0, 1)),
    pause_on_degraded_node INTEGER NOT NULL CHECK (pause_on_degraded_node IN (0, 1)),
    created_at             TEXT NOT NULL,
    updated_at             TEXT NOT NULL
) STRICT;
CREATE TABLE safety_policies (
    id                                 INTEGER PRIMARY KEY,
    slug                               TEXT NOT NULL UNIQUE,
    display_name                       TEXT NOT NULL,
    schema_version                     INTEGER NOT NULL CHECK (schema_version >= 1),
    auto_execute_operations            TEXT NOT NULL,
    backup_required                    INTEGER NOT NULL CHECK (backup_required IN (0, 1)),
    approval_required                  INTEGER NOT NULL CHECK (approval_required IN (0, 1)),
    allowed_commit_modes               TEXT NOT NULL,
    verification_level                 TEXT NOT NULL CHECK (verification_level IN (
                                           'none', 'quick_decode', 'full')),
    block_on_failed_records            INTEGER NOT NULL CHECK (block_on_failed_records IN (0, 1)),
    block_on_recovery_required_records INTEGER NOT NULL
                                           CHECK (block_on_recovery_required_records IN (0, 1)),
    created_at                         TEXT NOT NULL,
    updated_at                         TEXT NOT NULL
) STRICT;
CREATE TABLE workflow_file_run_starts (
    job_id                   INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    branch_id                TEXT NOT NULL,
    starting_file_version_id INTEGER NOT NULL REFERENCES file_versions(id) ON DELETE RESTRICT,
    starting_phase_ordinal   INTEGER NOT NULL CHECK (starting_phase_ordinal >= 0),
    PRIMARY KEY (job_id, branch_id)
) STRICT;
CREATE TABLE audio_extract_operations (
    id                          INTEGER PRIMARY KEY,
    operation_key               TEXT NOT NULL UNIQUE CHECK (length(operation_key) > 0),
    operation_id                TEXT CHECK (operation_id IS NULL OR length(operation_id) > 0),
    source_file_version_id      INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    source_bundle_id            INTEGER NOT NULL
        REFERENCES asset_bundles(id) ON DELETE RESTRICT,
    source_media_snapshot_id    INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    state                       TEXT NOT NULL
        CHECK (state IN ('planned','staged','prepared','recovery_required','committed')),
    dispatch_generation         INTEGER NOT NULL DEFAULT 0
        CHECK (dispatch_generation >= 0),
    claim_lease_id              INTEGER REFERENCES leases(id) ON DELETE RESTRICT,
    claim_token                 TEXT,
    claim_expires_at            TEXT,
    recovery_failure_class      TEXT,
    recovery_error_code         TEXT,
    recovery_message            TEXT,
    worker_result               TEXT CHECK (worker_result IS NULL OR json_valid(worker_result)),
    created_at                  TEXT NOT NULL,
    finished_at                 TEXT,
    CHECK (
        (claim_lease_id IS NULL AND claim_token IS NULL AND claim_expires_at IS NULL)
        OR
        (claim_lease_id IS NOT NULL AND length(claim_token) > 0
         AND claim_expires_at IS NOT NULL)
    ),
    CHECK (
        (state = 'committed' AND finished_at IS NOT NULL)
        OR
        (state != 'committed' AND finished_at IS NULL)
    ),
    CHECK (
        (state = 'recovery_required'
         AND recovery_failure_class IS NOT NULL
         AND recovery_error_code IS NOT NULL
         AND recovery_message IS NOT NULL)
        OR
        (state != 'recovery_required'
         AND recovery_failure_class IS NULL
         AND recovery_error_code IS NULL
         AND recovery_message IS NULL)
    )
) STRICT;
CREATE INDEX audio_extract_operations_by_source
    ON audio_extract_operations (source_file_version_id, id);
CREATE INDEX audio_extract_operations_by_state
    ON audio_extract_operations (state, id);
CREATE TABLE audio_extract_operation_outputs (
    id                           INTEGER PRIMARY KEY,
    operation_id                 INTEGER NOT NULL
        REFERENCES audio_extract_operations(id) ON DELETE CASCADE,
    ordinal                      INTEGER NOT NULL CHECK (ordinal >= 0),
    output_id                    TEXT,
    source_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(source_snapshot_stream_id) > 0),
    source_provider_stream_index INTEGER NOT NULL
        CHECK (source_provider_stream_index >= 0),
    bundle_role                  TEXT NOT NULL
        CHECK (bundle_role IN ('commentary_audio','external_audio')),
    target_path                  TEXT NOT NULL UNIQUE CHECK (length(target_path) > 0),
    staging_path                 TEXT,
    temp_path                    TEXT,
    expected_size_bytes          INTEGER CHECK (expected_size_bytes >= 0),
    expected_checksum            TEXT,
    artifact_handle_id           INTEGER UNIQUE
        REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    artifact_location_id         INTEGER UNIQUE
        REFERENCES artifact_locations(id) ON DELETE RESTRICT,
    verification_id              INTEGER UNIQUE
        REFERENCES artifact_verifications(id) ON DELETE RESTRICT,
    commit_record_id             INTEGER UNIQUE
        REFERENCES artifact_commit_records(id) ON DELETE RESTRICT,
    probe_worker_id              INTEGER REFERENCES workers(id) ON DELETE RESTRICT,
    probe_payload                TEXT CHECK (probe_payload IS NULL OR json_valid(probe_payload)),
    result_file_asset_id         INTEGER UNIQUE
        REFERENCES file_assets(id) ON DELETE RESTRICT,
    result_file_version_id       INTEGER UNIQUE
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    result_file_location_id      INTEGER UNIQUE
        REFERENCES file_locations(id) ON DELETE RESTRICT,
    result_media_snapshot_id     INTEGER UNIQUE
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    bundle_member_id             INTEGER UNIQUE
        REFERENCES asset_bundle_members(id) ON DELETE RESTRICT,
    result_facts                 TEXT CHECK (result_facts IS NULL OR json_valid(result_facts)),
    UNIQUE (operation_id, ordinal),
    UNIQUE (operation_id, output_id),
    CHECK (
        (expected_size_bytes IS NULL AND expected_checksum IS NULL)
        OR
        (expected_size_bytes IS NOT NULL AND expected_checksum IS NOT NULL)
    ),
    CHECK (
        (artifact_handle_id IS NULL AND artifact_location_id IS NULL)
        OR
        (artifact_handle_id IS NOT NULL AND artifact_location_id IS NOT NULL)
    ),
    CHECK (
        verification_id IS NULL
        OR (artifact_handle_id IS NOT NULL AND artifact_location_id IS NOT NULL)
    ),
    CHECK (
        (probe_worker_id IS NULL AND probe_payload IS NULL)
        OR
        (probe_worker_id IS NOT NULL AND probe_payload IS NOT NULL)
    ),
    CHECK (commit_record_id IS NULL OR verification_id IS NOT NULL),
    CHECK (
        (result_file_asset_id IS NULL
         AND result_file_version_id IS NULL
         AND result_file_location_id IS NULL
         AND result_media_snapshot_id IS NULL
         AND bundle_member_id IS NULL)
        OR
        (result_file_asset_id IS NOT NULL
         AND result_file_version_id IS NOT NULL
         AND result_file_location_id IS NOT NULL
         AND result_media_snapshot_id IS NOT NULL
         AND bundle_member_id IS NOT NULL)
    )
) STRICT;
CREATE TABLE audio_extract_dispatch_attempts (
    id                     INTEGER PRIMARY KEY,
    operation_id           INTEGER NOT NULL
        REFERENCES audio_extract_operations(id) ON DELETE CASCADE,
    generation             INTEGER NOT NULL CHECK (generation >= 0),
    worker_id              INTEGER NOT NULL REFERENCES workers(id) ON DELETE RESTRICT,
    worker_epoch           INTEGER NOT NULL CHECK (worker_epoch >= 0),
    idempotency_key        TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) > 0),
    attempt_directory      TEXT NOT NULL CHECK (length(attempt_directory) > 0),
    status                 TEXT NOT NULL
        CHECK (status IN ('active','terminal','quarantined','quiesced')),
    evidence_kind          TEXT
        CHECK (evidence_kind IS NULL OR evidence_kind IN
               ('terminal_response','operator_acknowledgement')),
    evidence_at            TEXT,
    acknowledged_by        TEXT,
    created_at             TEXT NOT NULL,
    CHECK (
        (status IN ('active','quarantined')
         AND evidence_kind IS NULL AND evidence_at IS NULL
         AND acknowledged_by IS NULL)
        OR
        (status = 'terminal'
         AND evidence_kind = 'terminal_response'
         AND evidence_at IS NOT NULL
         AND acknowledged_by IS NULL)
        OR
        (status = 'quiesced'
         AND evidence_kind = 'operator_acknowledgement'
         AND evidence_at IS NOT NULL
         AND length(acknowledged_by) > 0)
    ),
    UNIQUE (operation_id, generation)
) STRICT;
CREATE TABLE audio_extract_dispatch_attempt_paths (
    attempt_id   INTEGER NOT NULL
        REFERENCES audio_extract_dispatch_attempts(id) ON DELETE CASCADE,
    ordinal      INTEGER NOT NULL CHECK (ordinal >= 0),
    path         TEXT NOT NULL UNIQUE CHECK (length(path) > 0),
    PRIMARY KEY (attempt_id, ordinal)
) STRICT;
CREATE TABLE audio_extract_output_lineage (
    id                           INTEGER PRIMARY KEY,
    operation_output_id          INTEGER NOT NULL UNIQUE
        REFERENCES audio_extract_operation_outputs(id) ON DELETE RESTRICT,
    source_file_version_id       INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    source_media_snapshot_id     INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    source_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(source_snapshot_stream_id) > 0),
    source_provider_stream_index INTEGER NOT NULL
        CHECK (source_provider_stream_index >= 0),
    result_file_version_id       INTEGER NOT NULL UNIQUE
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    recorded_at                  TEXT NOT NULL
) STRICT;
CREATE INDEX audio_extract_lineage_by_source
    ON audio_extract_output_lineage (
        source_file_version_id,
        source_media_snapshot_id,
        source_provider_stream_index
    );
CREATE TABLE audio_synthesis_companions (
    id                           INTEGER PRIMARY KEY,
    operation_id                 INTEGER NOT NULL
        REFERENCES audio_synthesis_operations(id) ON DELETE CASCADE,
    ordinal                      INTEGER NOT NULL CHECK (ordinal >= 0),
    companion_id                 TEXT NOT NULL CHECK (length(companion_id) > 0),
    source_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(source_snapshot_stream_id) > 0),
    source_provider_stream_index INTEGER NOT NULL
        CHECK (source_provider_stream_index >= 0),
    result_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(result_snapshot_stream_id) > 0),
    result_provider_stream_index INTEGER CHECK (result_provider_stream_index >= 0),
    codec                        TEXT,
    channels                     INTEGER CHECK (channels > 0),
    language                     TEXT,
    title                        TEXT,
    disposition_default          INTEGER CHECK (disposition_default IN (0, 1)),
    disposition_forced           INTEGER CHECK (disposition_forced IN (0, 1)),
    disposition_commentary       INTEGER CHECK (disposition_commentary IN (0, 1)),
    result_facts                 TEXT CHECK (result_facts IS NULL OR json_valid(result_facts)),
    UNIQUE (operation_id, ordinal),
    UNIQUE (operation_id, companion_id),
    UNIQUE (operation_id, source_snapshot_stream_id),
    UNIQUE (operation_id, source_provider_stream_index),
    UNIQUE (operation_id, result_snapshot_stream_id),
    UNIQUE (operation_id, result_provider_stream_index),
    CHECK (companion_id = result_snapshot_stream_id)
) STRICT;
CREATE TABLE audio_synthesis_dispatch_attempts (
    id                     INTEGER PRIMARY KEY,
    operation_id           INTEGER NOT NULL
        REFERENCES audio_synthesis_operations(id) ON DELETE CASCADE,
    generation             INTEGER NOT NULL CHECK (generation >= 0),
    dispatch_lease_id      INTEGER NOT NULL REFERENCES leases(id) ON DELETE RESTRICT,
    worker_id              INTEGER NOT NULL REFERENCES workers(id) ON DELETE RESTRICT,
    worker_epoch           INTEGER NOT NULL CHECK (worker_epoch >= 0),
    idempotency_key        TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) > 0),
    attempt_directory      TEXT NOT NULL UNIQUE CHECK (length(attempt_directory) > 0),
    staging_path           TEXT NOT NULL UNIQUE CHECK (length(staging_path) > 0),
    status                 TEXT NOT NULL
        CHECK (status IN ('active','terminal','quarantined','quiesced')),
    evidence_kind          TEXT
        CHECK (evidence_kind IS NULL OR evidence_kind IN
               ('terminal_response','operator_acknowledgement')),
    evidence_at            TEXT,
    acknowledged_by        TEXT,
    created_at             TEXT NOT NULL,
    CHECK (
        (status IN ('active','quarantined')
         AND evidence_kind IS NULL AND evidence_at IS NULL
         AND acknowledged_by IS NULL)
        OR
        (status = 'terminal'
         AND evidence_kind = 'terminal_response'
         AND evidence_at IS NOT NULL
         AND acknowledged_by IS NULL)
        OR
        (status = 'quiesced'
         AND evidence_kind = 'operator_acknowledgement'
         AND evidence_at IS NOT NULL
         AND length(acknowledged_by) > 0)
    ),
    UNIQUE (operation_id, generation)
) STRICT;
CREATE TABLE audio_synthesis_stream_lineage (
    id                           INTEGER PRIMARY KEY,
    companion_id                 INTEGER NOT NULL UNIQUE
        REFERENCES audio_synthesis_companions(id) ON DELETE RESTRICT,
    source_file_version_id       INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    source_media_snapshot_id     INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    source_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(source_snapshot_stream_id) > 0),
    source_provider_stream_index INTEGER NOT NULL
        CHECK (source_provider_stream_index >= 0),
    result_file_version_id       INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    result_media_snapshot_id     INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    result_snapshot_stream_id    TEXT NOT NULL
        CHECK (length(result_snapshot_stream_id) > 0),
    result_provider_stream_index INTEGER NOT NULL
        CHECK (result_provider_stream_index >= 0),
    codec                        TEXT NOT NULL CHECK (length(codec) > 0),
    channels                     INTEGER NOT NULL CHECK (channels > 0),
    language                     TEXT,
    title                        TEXT,
    disposition_default          INTEGER NOT NULL CHECK (disposition_default IN (0, 1)),
    disposition_forced           INTEGER NOT NULL CHECK (disposition_forced IN (0, 1)),
    disposition_commentary       INTEGER NOT NULL
        CHECK (disposition_commentary IN (0, 1)),
    recorded_at                  TEXT NOT NULL,
    UNIQUE (result_media_snapshot_id, result_snapshot_stream_id),
    UNIQUE (result_media_snapshot_id, result_provider_stream_index)
) STRICT;
CREATE INDEX audio_synthesis_lineage_by_source
    ON audio_synthesis_stream_lineage (
        source_file_version_id,
        source_media_snapshot_id,
        source_provider_stream_index
    );
CREATE UNIQUE INDEX artifact_verifications_by_workflow_lease
    ON artifact_verifications (workflow_lease_id)
    WHERE workflow_lease_id IS NOT NULL;
CREATE INDEX artifact_verifications_by_workflow_ticket
    ON artifact_verifications (workflow_ticket_id, id)
    WHERE workflow_ticket_id IS NOT NULL;
CREATE INDEX artifact_commit_records_by_committed_result_version
    ON artifact_commit_records (result_file_version_id)
    WHERE state = 'committed';
CREATE TABLE "workflow_file_phase_summaries" (
    id                         INTEGER PRIMARY KEY,
    job_id                     INTEGER NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
    phase_ordinal              INTEGER NOT NULL CHECK (phase_ordinal >= 0),
    branch_id                  TEXT NOT NULL,
    ticket_ids                 TEXT NOT NULL CHECK (json_valid(ticket_ids)),
    produced_file_version_id   INTEGER REFERENCES file_versions(id) ON DELETE RESTRICT,
    produced_file_location_id  INTEGER REFERENCES file_locations(id) ON DELETE RESTRICT,
    artifact_handle_id         INTEGER REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    artifact_verification_id   INTEGER REFERENCES artifact_verifications(id) ON DELETE RESTRICT,
    reprobe_snapshot_id        INTEGER REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    outcome                    TEXT NOT NULL
        CHECK (outcome IN ('committed', 'verified', 'skipped', 'blocked')),
    created_at                 TEXT NOT NULL,
    CHECK (
        (outcome = 'committed'
            AND produced_file_version_id IS NOT NULL
            AND produced_file_location_id IS NOT NULL
            AND artifact_verification_id IS NULL
            AND reprobe_snapshot_id IS NOT NULL)
        OR (outcome = 'verified'
            AND produced_file_version_id IS NOT NULL
            AND produced_file_location_id IS NOT NULL
            AND artifact_handle_id IS NOT NULL
            AND artifact_verification_id IS NOT NULL
            AND reprobe_snapshot_id IS NOT NULL)
        OR (outcome IN ('skipped', 'blocked')
            AND produced_file_version_id IS NULL
            AND produced_file_location_id IS NULL
            AND artifact_handle_id IS NULL
            AND artifact_verification_id IS NULL
            AND reprobe_snapshot_id IS NULL)
    )
) STRICT;
CREATE UNIQUE INDEX workflow_file_phase_summaries_key
    ON workflow_file_phase_summaries (job_id, phase_ordinal, branch_id);
CREATE TABLE audio_synthesis_operations (
    id                          INTEGER PRIMARY KEY,
    operation_key               TEXT NOT NULL UNIQUE CHECK (length(operation_key) > 0),
    planned_operation_id        TEXT NOT NULL CHECK (length(planned_operation_id) > 0),
    source_file_version_id      INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    source_media_snapshot_id    INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    target_codec                TEXT NOT NULL CHECK (length(target_codec) > 0),
    target_channels             INTEGER NOT NULL CHECK (target_channels > 0),
    container                   TEXT NOT NULL CHECK (length(container) > 0),
    target_path                 TEXT NOT NULL UNIQUE CHECK (length(target_path) > 0),
    state                       TEXT NOT NULL
        CHECK (state IN ('planned','staged','committed')),
    dispatch_generation         INTEGER NOT NULL DEFAULT 0
        CHECK (dispatch_generation >= 0),
    claim_lease_id              INTEGER REFERENCES leases(id) ON DELETE RESTRICT,
    claim_token                 TEXT,
    claim_expires_at            TEXT,
    staging_path                TEXT UNIQUE,
    expected_size_bytes         INTEGER CHECK (expected_size_bytes >= 0),
    expected_checksum           TEXT,
    worker_result               TEXT CHECK (worker_result IS NULL OR json_valid(worker_result)),
    artifact_handle_id          INTEGER UNIQUE
        REFERENCES artifact_handles(id) ON DELETE RESTRICT,
    artifact_location_id        INTEGER UNIQUE
        REFERENCES artifact_locations(id) ON DELETE RESTRICT,
    verification_id             INTEGER UNIQUE
        REFERENCES artifact_verifications(id) ON DELETE RESTRICT,
    commit_record_id            INTEGER UNIQUE
        REFERENCES artifact_commit_records(id) ON DELETE RESTRICT,
    probe_worker_id             INTEGER REFERENCES workers(id) ON DELETE RESTRICT,
    probe_payload               TEXT CHECK (probe_payload IS NULL OR json_valid(probe_payload)),
    result_file_asset_id        INTEGER
        REFERENCES file_assets(id) ON DELETE RESTRICT,
    result_file_version_id      INTEGER UNIQUE
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    result_file_location_id     INTEGER UNIQUE
        REFERENCES file_locations(id) ON DELETE RESTRICT,
    result_media_snapshot_id    INTEGER UNIQUE
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    created_at                  TEXT NOT NULL,
    finished_at                 TEXT,
    CHECK (
        (claim_lease_id IS NULL AND claim_token IS NULL AND claim_expires_at IS NULL)
        OR
        (claim_lease_id IS NOT NULL AND length(claim_token) > 0
         AND claim_expires_at IS NOT NULL)
    ),
    CHECK (
        (expected_size_bytes IS NULL AND expected_checksum IS NULL)
        OR
        (expected_size_bytes IS NOT NULL AND expected_checksum IS NOT NULL)
    ),
    CHECK (
        (artifact_handle_id IS NULL AND artifact_location_id IS NULL)
        OR
        (artifact_handle_id IS NOT NULL AND artifact_location_id IS NOT NULL)
    ),
    CHECK (
        verification_id IS NULL
        OR (artifact_handle_id IS NOT NULL AND artifact_location_id IS NOT NULL)
    ),
    CHECK (commit_record_id IS NULL OR verification_id IS NOT NULL),
    CHECK (
        (probe_worker_id IS NULL AND probe_payload IS NULL)
        OR
        (probe_worker_id IS NOT NULL AND probe_payload IS NOT NULL)
    ),
    CHECK (
        (result_file_asset_id IS NULL
         AND result_file_version_id IS NULL
         AND result_file_location_id IS NULL
         AND result_media_snapshot_id IS NULL)
        OR
        (result_file_asset_id IS NOT NULL
         AND result_file_version_id IS NOT NULL
         AND result_file_location_id IS NOT NULL
         AND result_media_snapshot_id IS NOT NULL)
    ),
    CHECK (
        (state = 'committed' AND finished_at IS NOT NULL)
        OR
        (state != 'committed' AND finished_at IS NULL)
    )
) STRICT;
CREATE INDEX audio_synthesis_operations_by_source
    ON audio_synthesis_operations (source_file_version_id, id);
CREATE INDEX audio_synthesis_operations_by_state
    ON audio_synthesis_operations (state, id);
CREATE TABLE workflow_file_windows (
    job_id              INTEGER PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,
    max_in_flight_files INTEGER NOT NULL CHECK (max_in_flight_files > 0),
    created_at          TEXT NOT NULL
) STRICT;
CREATE TABLE workflow_file_progress (
    job_id             INTEGER NOT NULL,
    branch_id          TEXT NOT NULL,
    input_ordinal      INTEGER NOT NULL CHECK (input_ordinal >= 0),
    admission_tier     INTEGER NOT NULL CHECK (admission_tier IN (0, 1)),
    state              TEXT NOT NULL
        CHECK (state IN ('pending', 'active', 'terminalizing', 'terminal')),
    next_phase_ordinal INTEGER NOT NULL CHECK (next_phase_ordinal >= 0),
    admitted_at        TEXT,
    terminal_at        TEXT,
    PRIMARY KEY (job_id, branch_id),
    UNIQUE (job_id, input_ordinal),
    FOREIGN KEY (job_id, branch_id)
        REFERENCES workflow_file_run_starts (job_id, branch_id)
        ON DELETE CASCADE,
    CHECK (
        (state = 'pending' AND admitted_at IS NULL AND terminal_at IS NULL)
        OR (state = 'active' AND admitted_at IS NOT NULL AND terminal_at IS NULL)
        OR (state = 'terminalizing' AND admitted_at IS NOT NULL AND terminal_at IS NULL)
        OR (state = 'terminal' AND admitted_at IS NOT NULL AND terminal_at IS NOT NULL)
    )
) STRICT;
CREATE INDEX workflow_file_progress_admission
    ON workflow_file_progress (job_id, state, admission_tier, input_ordinal);
CREATE TABLE workflow_file_phase_entries (
    job_id            INTEGER NOT NULL,
    phase_ordinal     INTEGER NOT NULL CHECK (phase_ordinal >= 0),
    branch_id         TEXT NOT NULL,
    media_snapshot_id INTEGER NOT NULL
        REFERENCES media_snapshots(id) ON DELETE RESTRICT,
    gate_admitted     INTEGER NOT NULL CHECK (gate_admitted IN (0, 1)),
    created_at        TEXT NOT NULL,
    PRIMARY KEY (job_id, phase_ordinal, branch_id),
    FOREIGN KEY (job_id, branch_id)
        REFERENCES workflow_file_run_starts (job_id, branch_id)
        ON DELETE CASCADE
) STRICT;
CREATE TABLE "workflow_file_run_history" (
    job_id        INTEGER NOT NULL,
    branch_id     TEXT NOT NULL,
    phase_ordinal INTEGER NOT NULL CHECK (phase_ordinal >= 0),
    outcome       TEXT NOT NULL
        CHECK (outcome IN ('committed', 'verified', 'skipped', 'blocked')),
    PRIMARY KEY (job_id, branch_id, phase_ordinal),
    FOREIGN KEY (job_id, branch_id)
        REFERENCES workflow_file_run_starts (job_id, branch_id)
        ON DELETE CASCADE
) STRICT;
CREATE TABLE "video_profiles" (
  id               TEXT PRIMARY KEY,
  name             TEXT NOT NULL UNIQUE,
  target_codec     TEXT NOT NULL,
  encoder          TEXT NOT NULL,
  crf              INTEGER,
  cq               INTEGER,
  qp               INTEGER,
  bitrate_kbps     INTEGER,
  preset           TEXT,
  tune             TEXT,
  codec_profile    TEXT,
  codec_level      TEXT,
  pixel_format     TEXT,
  max_width        INTEGER,
  max_height       INTEGER,
  output_container TEXT NOT NULL DEFAULT 'mkv',
  copy_compatible  INTEGER NOT NULL DEFAULT 0,
  retired_at       TEXT,
  decode_backend   TEXT NOT NULL DEFAULT 'software',
  CHECK (length(trim(name)) > 0),
  CHECK (target_codec IN ('h264', 'hevc', 'av1')),
  CHECK (
    encoder IN (
      'libx265',
      'libsvtav1',
      'libaom-av1',
      'hevc_nvenc',
      'h264_videotoolbox',
      'hevc_videotoolbox',
      'hevc_vaapi'
    )
  ),
  -- Exactly one quality field per encoder, the one its QualityDomain names in
  -- voom-core. `qp` excludes 0 because hevc_vaapi reads 0 as "auto", which is
  -- not an operator quality target.
  --
  -- Each arm asserts its own field IS NOT NULL before the range test: SQLite
  -- treats a CHECK that evaluates to NULL as satisfied, so a bare
  -- `cq BETWEEN 1 AND 51` admits a row with no quality field at all.
  CHECK (
    (encoder IN ('h264_videotoolbox', 'hevc_videotoolbox')
      AND crf IS NULL AND cq IS NULL AND qp IS NULL
      AND bitrate_kbps IS NOT NULL AND bitrate_kbps BETWEEN 1 AND 4294967295)
    OR
    (encoder = 'hevc_nvenc'
      AND crf IS NULL AND qp IS NULL AND bitrate_kbps IS NULL
      AND cq IS NOT NULL AND cq BETWEEN 1 AND 51)
    OR
    (encoder = 'hevc_vaapi'
      AND crf IS NULL AND cq IS NULL AND bitrate_kbps IS NULL
      AND qp IS NOT NULL AND qp BETWEEN 1 AND 52)
    OR
    (encoder IN ('libx265', 'libsvtav1', 'libaom-av1')
      AND cq IS NULL AND qp IS NULL AND bitrate_kbps IS NULL
      AND crf IS NOT NULL AND crf >= 0)
  ),
  CHECK (
    (encoder = 'hevc_vaapi' AND preset IS NULL)
    OR
    (encoder != 'hevc_vaapi' AND preset IS NOT NULL)
  ),
  CHECK (max_width IS NULL OR max_width > 0),
  CHECK (max_height IS NULL OR max_height > 0),
  CHECK (output_container IN ('mkv', 'mp4')),
  CHECK (copy_compatible IN (0, 1)),
  CHECK (decode_backend IN ('software', 'nvidia', 'video_toolbox', 'vaapi')),
  CHECK (
    decode_backend = 'software'
    OR (decode_backend = 'nvidia' AND encoder = 'hevc_nvenc')
    OR (
      decode_backend = 'video_toolbox'
      AND encoder IN ('h264_videotoolbox', 'hevc_videotoolbox')
    )
    OR (decode_backend = 'vaapi' AND encoder = 'hevc_vaapi')
  )
) STRICT;
CREATE TABLE "accelerator_claims" (
  hardware_token            TEXT PRIMARY KEY,
  backend                   TEXT NOT NULL,
  worker_id                 INTEGER NOT NULL UNIQUE REFERENCES workers(id) ON DELETE RESTRICT,
  boot_id                   TEXT NOT NULL,
  supervisor_pid            INTEGER NOT NULL,
  supervisor_start_identity TEXT,
  process_group_id          INTEGER NOT NULL,
  capacity                  INTEGER NOT NULL,
  claimed_at                TEXT NOT NULL,
  CHECK (length(trim(hardware_token)) > 0),
  CHECK (backend IN ('nvidia', 'video_toolbox', 'vaapi')),
  CHECK (supervisor_pid > 0),
  CHECK (
    (backend IN ('nvidia', 'vaapi') AND supervisor_start_identity IS NOT NULL)
    OR (backend = 'video_toolbox' AND supervisor_start_identity IS NULL)
  ),
  CHECK (process_group_id > 0),
  CHECK (capacity BETWEEN 1 AND 16)
) STRICT;
CREATE TABLE library_roots (
    id                       INTEGER PRIMARY KEY,
    library_id               INTEGER NOT NULL
        REFERENCES libraries(id) ON DELETE RESTRICT,
    owner_node_id            INTEGER REFERENCES nodes(id) ON DELETE RESTRICT,
    provider_kind            TEXT NOT NULL
        CHECK (provider_kind IN ('local_filesystem')),
    provider_locator         TEXT NOT NULL
        CHECK (length(CAST(provider_locator AS BLOB)) BETWEEN 1 AND 4096)
        CHECK (instr(provider_locator, char(0)) = 0),
    display_locator          TEXT NOT NULL,
    state                    TEXT NOT NULL
        CHECK (state IN ('unassigned', 'configured', 'active', 'unavailable', 'retired')),
    root_epoch               INTEGER NOT NULL DEFAULT 0 CHECK (root_epoch >= 0),
    activation_identity      TEXT CHECK (
        activation_identity IS NULL
        OR (
            length(CAST(activation_identity AS BLOB)) BETWEEN 1 AND 4096
            AND instr(activation_identity, char(0)) = 0
        )
    ),
    include_globs            TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(include_globs)),
    exclude_globs            TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(exclude_globs)),
    extension_allowlist      TEXT NOT NULL DEFAULT '[]'
        CHECK (json_valid(extension_allowlist)),
    scan_mode                TEXT NOT NULL
        CHECK (scan_mode IN ('explicit_only', 'manual_recursive', 'watch_enabled')),
    symlink_policy           TEXT NOT NULL CHECK (symlink_policy IN ('reject', 'follow')),
    hidden_file_policy       TEXT NOT NULL CHECK (hidden_file_policy IN ('ignore', 'include')),
    max_depth                INTEGER CHECK (max_depth IS NULL OR max_depth >= 0),
    stability_seconds        INTEGER NOT NULL DEFAULT 0 CHECK (stability_seconds >= 0),
    debounce_seconds         INTEGER NOT NULL DEFAULT 0 CHECK (debounce_seconds >= 0),
    default_output_root_id   INTEGER REFERENCES library_roots(id) ON DELETE RESTRICT,
    default_staging_root_id  INTEGER REFERENCES library_roots(id) ON DELETE RESTRICT,
    default_backup_root_id   INTEGER REFERENCES library_roots(id) ON DELETE RESTRICT,
    enabled                  INTEGER NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    created_at               TEXT NOT NULL,
    updated_at               TEXT NOT NULL, last_scan_session_id INTEGER
    REFERENCES scan_sessions(id) ON DELETE RESTRICT,
    CHECK (
        (state = 'unassigned' AND owner_node_id IS NULL AND activation_identity IS NULL)
        OR
        (state = 'configured' AND owner_node_id IS NOT NULL AND activation_identity IS NULL)
        OR
        (state IN ('active', 'unavailable')
         AND owner_node_id IS NOT NULL AND activation_identity IS NOT NULL)
        OR
        (state = 'retired'
         AND (owner_node_id IS NOT NULL OR activation_identity IS NULL))
    )
) STRICT;
CREATE INDEX library_roots_by_library ON library_roots (library_id, id);
CREATE INDEX library_roots_by_owner_state
    ON library_roots (owner_node_id, state, id)
    WHERE owner_node_id IS NOT NULL;
CREATE UNIQUE INDEX library_roots_owner_provider_locator
    ON library_roots (owner_node_id, provider_kind, provider_locator)
    WHERE owner_node_id IS NOT NULL AND state != 'retired';
CREATE TABLE file_locations (
    id                            INTEGER PRIMARY KEY,
    file_version_id               INTEGER NOT NULL
        REFERENCES file_versions(id) ON DELETE RESTRICT,
    address_state                 TEXT NOT NULL
        CHECK (address_state IN ('rooted', 'unassigned_legacy')),
    storage_root_id               INTEGER
        REFERENCES library_roots(id) ON DELETE RESTRICT,
    provider_relative_locator     TEXT,
    legacy_kind                   TEXT CHECK (
        legacy_kind IS NULL OR legacy_kind IN (
            'local_path', 'shared_mount', 'object_store_key', 'backup_path', 'historical'
        )
    ),
    legacy_locator                TEXT,
    proof_kind                    TEXT CHECK (
        proof_kind IS NULL OR proof_kind IN ('file_id_generation', 'object_version_id')
    ),
    proof_value                   TEXT,
    observed_at                   TEXT NOT NULL,
    retired_at                    TEXT,
    epoch                         INTEGER NOT NULL DEFAULT 0 CHECK (epoch >= 0), retired_by_scan_session_id INTEGER
    REFERENCES scan_sessions(id) ON DELETE RESTRICT
    CHECK (retired_by_scan_session_id IS NULL OR retired_at IS NOT NULL),
    CHECK (
        (address_state = 'rooted'
         AND storage_root_id IS NOT NULL
         AND provider_relative_locator IS NOT NULL
         AND legacy_kind IS NULL
         AND legacy_locator IS NULL)
        OR
        (address_state = 'unassigned_legacy'
         AND storage_root_id IS NULL
         AND provider_relative_locator IS NULL
         AND legacy_kind IS NOT NULL
         AND legacy_locator IS NOT NULL)
    ),
    CHECK (
        provider_relative_locator IS NULL
        OR (
            length(CAST(provider_relative_locator AS BLOB)) BETWEEN 1 AND 4096
            AND instr(provider_relative_locator, char(0)) = 0
            AND instr(provider_relative_locator, '\') = 0
            AND substr(provider_relative_locator, 1, 1) != '/'
            AND substr(provider_relative_locator, -1, 1) != '/'
            AND instr(provider_relative_locator, '//') = 0
            AND instr('/' || provider_relative_locator || '/', '/./') = 0
            AND instr('/' || provider_relative_locator || '/', '/../') = 0
        )
    ),
    CHECK (
        (proof_kind IS NULL AND proof_value IS NULL)
        OR (proof_kind IS NOT NULL AND proof_value IS NOT NULL)
    )
) STRICT;
CREATE INDEX file_locations_by_version ON file_locations (file_version_id);
CREATE INDEX file_locations_live
    ON file_locations (file_version_id) WHERE retired_at IS NULL;
CREATE INDEX file_locations_by_root
    ON file_locations (storage_root_id, id) WHERE storage_root_id IS NOT NULL;
CREATE UNIQUE INDEX file_locations_live_rooted_address
    ON file_locations (storage_root_id, provider_relative_locator)
    WHERE address_state = 'rooted' AND retired_at IS NULL;
CREATE TABLE node_incarnations (
    incarnation_id TEXT PRIMARY KEY,
    node_id INTEGER NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT,
    status TEXT NOT NULL CHECK (status IN ('active', 'superseded', 'retired', 'failed')),
    started_at TEXT NOT NULL,
    last_seen_at TEXT NOT NULL,
    ended_at TEXT,
    end_reason TEXT,
    CHECK (
        (status = 'active' AND ended_at IS NULL AND end_reason IS NULL)
        OR (status = 'superseded' AND ended_at IS NOT NULL AND end_reason = 'superseded')
        OR (
            status = 'retired'
            AND ended_at IS NOT NULL
            AND end_reason IN ('graceful_shutdown', 'logical_node_retired')
        )
        OR (
            status = 'failed'
            AND ended_at IS NOT NULL
            AND end_reason IN (
                'child_startup_failed',
                'child_restart_exhausted',
                'heartbeat_expired'
            )
        )
    )
) STRICT;
CREATE UNIQUE INDEX node_incarnations_one_active_per_node
    ON node_incarnations(node_id)
    WHERE status = 'active';
CREATE INDEX node_incarnations_history
    ON node_incarnations(node_id, started_at DESC, incarnation_id DESC);
CREATE INDEX workers_node_incarnation
    ON workers(node_incarnation_id, id);
CREATE UNIQUE INDEX file_locations_scan_watermark_root
ON file_locations(id, storage_root_id);
CREATE UNIQUE INDEX node_incarnations_owner_binding
ON node_incarnations(incarnation_id, node_id);
CREATE TABLE scan_sessions (
    id                          INTEGER PRIMARY KEY,
    storage_root_id             INTEGER NOT NULL
        REFERENCES library_roots(id) ON DELETE RESTRICT,
    root_epoch                  INTEGER NOT NULL CHECK (root_epoch >= 0),
    owner_node_id               INTEGER NOT NULL REFERENCES nodes(id) ON DELETE RESTRICT,
    owner_incarnation_id        TEXT,
    status                      TEXT NOT NULL
        CHECK (status IN ('requested', 'running', 'succeeded', 'failed', 'cancelled', 'stale')),
    next_sequence               INTEGER NOT NULL DEFAULT 0 CHECK (next_sequence >= 0),
    batch_count                 INTEGER NOT NULL DEFAULT 0 CHECK (batch_count >= 0),
    observation_count           INTEGER NOT NULL DEFAULT 0
        CHECK (observation_count BETWEEN 0 AND 100000),
    idle_timeout_seconds        INTEGER NOT NULL CHECK (idle_timeout_seconds BETWEEN 1 AND 86400),
    progress_deadline_at        TEXT NOT NULL,
    location_high_watermark_id  INTEGER,
    requested_at                TEXT NOT NULL,
    started_at                  TEXT,
    terminal_at                 TEXT,
    terminal_reason             TEXT CHECK (
        terminal_reason IS NULL
        OR (
            length(CAST(terminal_reason AS BLOB)) BETWEEN 1 AND 1024
            AND instr(terminal_reason, char(0)) = 0
            AND length(trim(
                terminal_reason,
                char(9) || char(10) || char(11) || char(12) || char(13) || char(32)
            )) > 0
        )
    ),
    retired_location_count      INTEGER NOT NULL DEFAULT 0 CHECK (
        retired_location_count >= 0
        AND (status = 'succeeded' OR retired_location_count = 0)
    ),
    FOREIGN KEY (location_high_watermark_id, storage_root_id)
        REFERENCES file_locations(id, storage_root_id) ON DELETE RESTRICT,
    FOREIGN KEY (owner_incarnation_id, owner_node_id)
        REFERENCES node_incarnations(incarnation_id, node_id) ON DELETE RESTRICT,
    CHECK (
        batch_count = next_sequence
        AND (
            (batch_count = 0 AND observation_count = 0)
            OR (
                batch_count > 0
                AND observation_count >= batch_count
                AND (
                    observation_count / batch_count < 1000
                    OR (
                        observation_count / batch_count = 1000
                        AND observation_count % batch_count = 0
                    )
                )
            )
        )
    ),
    CHECK (
        (status = 'requested'
         AND owner_incarnation_id IS NULL
         AND started_at IS NULL
         AND location_high_watermark_id IS NULL
         AND terminal_at IS NULL
         AND terminal_reason IS NULL)
        OR
        (status = 'running'
         AND owner_incarnation_id IS NOT NULL
         AND started_at IS NOT NULL
         AND terminal_at IS NULL
         AND terminal_reason IS NULL)
        OR
        (status = 'succeeded'
         AND owner_incarnation_id IS NOT NULL
         AND started_at IS NOT NULL
         AND terminal_at IS NOT NULL
         AND terminal_reason IS NULL)
        OR
        (status IN ('failed', 'cancelled', 'stale')
         AND terminal_at IS NOT NULL
         AND terminal_reason IS NOT NULL
         AND (
             (owner_incarnation_id IS NULL
              AND started_at IS NULL
              AND location_high_watermark_id IS NULL)
             OR (owner_incarnation_id IS NOT NULL AND started_at IS NOT NULL)
         ))
    )
) STRICT;
CREATE UNIQUE INDEX scan_sessions_one_active_per_root
ON scan_sessions(storage_root_id)
WHERE status IN ('requested', 'running');
CREATE INDEX scan_sessions_active_deadline
ON scan_sessions(status, progress_deadline_at, id)
WHERE status IN ('requested', 'running');
CREATE INDEX scan_sessions_by_root_requested_at
ON scan_sessions(storage_root_id, requested_at DESC, id DESC);
CREATE TABLE scan_observation_batches (
    scan_session_id             INTEGER NOT NULL
        REFERENCES scan_sessions(id) ON DELETE RESTRICT,
    sequence                    INTEGER NOT NULL CHECK (sequence >= 0),
    previous_sequence           INTEGER,
    request_hash                TEXT NOT NULL
        CHECK (length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'),
    observation_count           INTEGER NOT NULL CHECK (observation_count BETWEEN 1 AND 1000),
    accepted_at                 TEXT NOT NULL,
    cumulative_observation_count INTEGER NOT NULL
        CHECK (cumulative_observation_count BETWEEN observation_count AND 100000),
    PRIMARY KEY (scan_session_id, sequence),
    FOREIGN KEY (scan_session_id, previous_sequence)
        REFERENCES scan_observation_batches(scan_session_id, sequence) ON DELETE RESTRICT,
    CHECK (
        (sequence = 0 AND previous_sequence IS NULL)
        OR (sequence > 0 AND previous_sequence = sequence - 1)
    )
) STRICT;
CREATE TRIGGER scan_observation_batches_validate_insert
BEFORE INSERT ON scan_observation_batches
BEGIN
    SELECT CASE
        WHEN NEW.sequence > 0 AND NOT EXISTS (
            SELECT 1 FROM scan_observation_batches AS predecessor
            WHERE predecessor.scan_session_id = NEW.scan_session_id
              AND predecessor.sequence = NEW.previous_sequence
        )
        THEN RAISE(ABORT, 'scan observation batch predecessor missing')
    END;
    SELECT CASE
        WHEN NEW.sequence = 0
             AND NEW.cumulative_observation_count != NEW.observation_count
        THEN RAISE(ABORT, 'scan observation batch cumulative count mismatch')
        WHEN NEW.sequence > 0 AND NEW.cumulative_observation_count != (
            SELECT predecessor.cumulative_observation_count + NEW.observation_count
            FROM scan_observation_batches AS predecessor
            WHERE predecessor.scan_session_id = NEW.scan_session_id
              AND predecessor.sequence = NEW.previous_sequence
        )
        THEN RAISE(ABORT, 'scan observation batch cumulative count mismatch')
    END;
END;
CREATE TRIGGER scan_observation_batches_validate_parent_frontier
BEFORE INSERT ON scan_observation_batches
BEGIN
    SELECT CASE
        WHEN NOT EXISTS (
            SELECT 1 FROM scan_sessions AS session
            WHERE session.id = NEW.scan_session_id
              AND session.next_sequence = NEW.sequence + 1
              AND session.batch_count = NEW.sequence + 1
              AND session.observation_count = NEW.cumulative_observation_count
        )
        THEN RAISE(ABORT, 'scan observation batch parent frontier mismatch')
    END;
END;
CREATE TRIGGER scan_observation_batches_no_update
BEFORE UPDATE ON scan_observation_batches
BEGIN
    SELECT RAISE(ABORT, 'scan observation batch rows are immutable');
END;
CREATE TRIGGER scan_observation_batches_no_delete
BEFORE DELETE ON scan_observation_batches
BEGIN
    SELECT RAISE(ABORT, 'scan observation batch rows are immutable');
END;
CREATE TABLE scan_observations (
    scan_session_id             INTEGER NOT NULL,
    batch_sequence              INTEGER NOT NULL CHECK (batch_sequence >= 0),
    ordinal                     INTEGER NOT NULL CHECK (ordinal >= 0),
    provider_relative_locator   TEXT NOT NULL CHECK (
        length(CAST(provider_relative_locator AS BLOB)) BETWEEN 1 AND 4096
        AND instr(provider_relative_locator, char(0)) = 0
        AND instr(provider_relative_locator, char(92)) = 0
        AND substr(provider_relative_locator, 1, 1) != '/'
        AND substr(provider_relative_locator, -1, 1) != '/'
        AND instr(provider_relative_locator, '//') = 0
        AND instr('/' || provider_relative_locator || '/', '/./') = 0
        AND instr('/' || provider_relative_locator || '/', '/../') = 0
    ),
    provider_object_identity    TEXT NOT NULL CHECK (
        length(CAST(provider_object_identity AS BLOB)) BETWEEN 1 AND 4096
        AND instr(provider_object_identity, char(0)) = 0
    ),
    size_bytes                  INTEGER NOT NULL CHECK (size_bytes >= 0),
    modified_at                 TEXT NOT NULL,
    stability_started_at        TEXT NOT NULL,
    stability_confirmed_at      TEXT NOT NULL CHECK (stability_confirmed_at >= stability_started_at),
    PRIMARY KEY (scan_session_id, batch_sequence, ordinal),
    FOREIGN KEY (scan_session_id, batch_sequence)
        REFERENCES scan_observation_batches(scan_session_id, sequence) ON DELETE RESTRICT
) STRICT;
CREATE UNIQUE INDEX scan_observations_one_locator_per_session
ON scan_observations(scan_session_id, provider_relative_locator);
CREATE INDEX file_locations_by_retired_scan_session
ON file_locations(retired_by_scan_session_id, id);

